INSERT IGNORE INTO `cms_documents` (`key`, `data`, `status`, `updated_at`, `updated_by`) VALUES ('home_sections', '{"ctaCopy": "Tell us where your business is stuck. We will reply with a clear, honest recommendation, technology, marketing, AI or all three.", "formPoints": ["An honest reply within 1 business day", "A clear recommendation, not a sales pitch", "Scope, stack and timeline in plain language"], "ctaHeadline": "Ready to connect, grow and achieve?", "formEyebrow": "Get started", "formHeading": "Tell us where growth is stuck", "teamCtaCopy": "Engineers, designers, marketers and automation specialists working as one pod, with a founder who stays on your project from first call to launch.", "techEyebrow": "Technology", "techHeading": "The stack we build on", "statsEyebrow": "Trusted partner", "statsHeading": "The numbers behind how we work", "teamCtaLabel": "Get to Know Our Team", "whyUsEyebrow": "Why choose us", "whyUsHeading": "Six reasons clients stay", "processEyebrow": "How we work", "processHeading": "Discover \\u2192 Strategize \\u2192 Build \\u2192 Launch \\u2192 Optimize", "teamCtaEyebrow": "The people behind the work", "teamCtaHeading": "A 15+ member team, led hands-on by Vrajesh Patel", "formDescription": "Share a few details and you will get an honest recommendation, or book a 30-minute strategy call straight away.", "presenceSubline": "premium websites, marketing systems and AI automation delivered from Ahmedabad.", "problemsEyebrow": "The problem", "problemsHeading": "Growth stalls when your digital system is disconnected", "techDescription": "Modern, well-supported technology chosen for performance, security and long-term maintainability.", "servicesAllLabel": "View All Services", "solutionsEyebrow": "The solution", "solutionsHeading": "One partner for technology, marketing and AI", "statsDescription": "We publish verified capability figures only. Client and result numbers go live once they are confirmed with each brand.", "whyUsDescription": "One accountable partner across strategy, build, marketing and automation.", "philosophyEyebrow": "Our philosophy", "philosophyHeading": "\\u2022 Connect \\u2022 Grow \\u2022 Achieve", "processDescription": "A clear path from first call to measurable results.", "problemsDescription": "Most businesses do not have a marketing problem or a technology problem. They have a coordination problem.", "solutionsDescription": "Three capabilities, built as one system so every part supports the next.", "philosophyDescription": "A simple operating model that keeps technology, marketing and automation pointed at one commercial outcome."}', 'published', '2026-08-18 10:32:36', NULL);
