INSERT IGNORE INTO `cms_documents` (`key`, `data`, `status`, `updated_at`, `updated_by`) VALUES ('about_sections', '{"ctaCopy": "Share your goal and we will tell you honestly what will move the needle first.", "heroIntro": "Work With Vrajesh is a technology, marketing and AI solutions partner that helps businesses build better digital experiences, generate more opportunities and automate what matters.", "ctaHeadline": "Let''s talk about your next move", "founderIntro": "Work With Vrajesh is a founder-led practice. I work with businesses that want technology, marketing and AI handled by someone who understands all three and stays accountable for the result.", "whyUsHeading": "Why businesses choose Work With Vrajesh", "visionSupport": "One partner, one plan, so technology, marketing and AI stop working in separate silos and start compounding.", "founderEyebrow": "Founder", "founderHeading": "Meet Vrajesh Patel", "missionSupport": "Credible presence, consistent opportunities, less manual work, measured in inquiries and replies, not impressions.", "processHeading": "Our process", "presenceSubline": "founder-led technology, marketing and AI delivery across time zones.", "heroHeadlineLead": "Founder-led. Team-powered.", "heroHeadlineAccent": "Outcome-obsessed.", "testimonialsHeading": "Trusted by the brands we work with", "visionMissionEyebrow": "Why we exist", "testimonialsDescription": "Client feedback from India, Australia, Canada, Europe, the UK, Africa, the USA and the Middle East on delivery, communication and results."}', 'published', '2026-08-17 19:36:16', NULL);
