INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('9ed21417-d3b0-44ca-81fb-ce222f4e184e', 'testimonials', 'rohit-mehta', 0, 'published', '{"id": "rohit-mehta", "quote": "We came in with a messy old site and a lot of doubts. Vrajesh asked better questions than any agency we spoke to, and the new site actually explains what we do. Enquiries went from a trickle to something we now have to manage.", "company": "Mehta Interiors", "featured": true, "location": "Ahmedabad, India", "clientName": "Rohit Mehta", "designation": "Director", "serviceUsed": "Website Development"}', '2026-08-17 14:05:32', '2026-08-17 14:05:32', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('0a9330fe-ad57-4934-bc4e-31f4614792c8', 'testimonials', 'shruti-nair', 1, 'published', '{"id": "shruti-nair", "quote": "Our social pages used to be random posts whenever someone had time. Now there is a plan, the tone sounds like us, and people mention our content in sales calls. That change alone was worth it.", "company": "Bluecrest Clinics", "featured": true, "location": "Mumbai, India", "clientName": "Shruti Nair", "designation": "Marketing Head", "serviceUsed": "Social Media Marketing"}', '2026-08-17 14:05:32', '2026-08-17 14:05:32', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('d752db60-95fa-4804-9462-a97fcd14a6d7', 'testimonials', 'emily-harper', 3, 'published', '{"id": "emily-harper", "quote": "The WhatsApp automation quietly handles the first round of questions now. My front desk stopped drowning in the same three enquiries and we still catch every lead after hours.", "company": "Lakeside Dental", "location": "Toronto, Canada", "clientName": "Emily Harper", "designation": "Operations Manager", "serviceUsed": "WhatsApp Automation"}', '2026-08-17 14:05:32', '2026-08-17 14:05:32', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('19eb49ca-5146-4304-bab1-faa8b2974a15', 'testimonials', 'omar-al-farsi', 4, 'published', '{"id": "omar-al-farsi", "quote": "We tested Meta ads on our own for months and burned budget. Vrajesh rebuilt the offer and the creative angle first, then the ads. Cost per lead dropped and, more importantly, the leads pick up the phone.", "company": "Zenith Realty Group", "location": "Dubai, UAE", "clientName": "Omar Al Farsi", "designation": "Managing Partner", "serviceUsed": "Meta Ads"}', '2026-08-17 14:05:32', '2026-08-17 14:05:32', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('a56551b7-6060-4ed3-9c90-63ce6fe50c5a', 'testimonials', 'linh-tran', 5, 'published', '{"id": "linh-tran", "quote": "The chatbot understands our product questions properly instead of throwing a canned reply. Support tickets are down noticeably and our team only steps in when it actually matters.", "company": "Formly SaaS", "location": "Singapore", "clientName": "Linh Tran", "designation": "Product Lead", "serviceUsed": "Chatbot Solutions"}', '2026-08-17 14:05:32', '2026-08-17 14:05:32', NULL);
