INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('07fe1640-9a3b-4edd-8f37-65509aa5c654', 'case_studies', 'multilingual-property-portal-uae', 3, 'published', '{"slug": "multilingual-property-portal-uae", "team": "1 strategist, 1 designer, 2 developers, 1 QA", "title": "A multilingual property portal built for fast mobile enquiries", "country": "United Arab Emirates", "metrics": [], "features": ["RTL/LTR mirrored design system", "Map and area-based listing search", "Saved searches and shortlists", "Agent-routed enquiry and WhatsApp handoff", "hreflang and structured listing data"], "industry": "Real estate", "outcomes": ["Arabic-speaking buyers get the same experience as English-speaking buyers", "Agents receive enquiries on their phone with full listing context", "Listing data is entered once and stays consistent everywhere"], "solution": [{"title": "True bilingual architecture", "description": "Mirrored RTL and LTR layouts with language-specific URLs, metadata and typography rather than a translation overlay."}, {"title": "Media pipeline", "description": "Responsive image delivery, lazy galleries and video posters tuned for mobile data connections."}, {"title": "Single listing source", "description": "One listing record feeding both languages, the search index and the portal feeds."}, {"title": "Instant enquiry routing", "description": "Enquiries assigned by listing owner with WhatsApp and call handoff, logged to CRM."}], "challenge": "Most visitors arrived on mobile from social ads, but listing pages were heavy with unoptimised photography and the Arabic version was a partial translation with broken layout. Listings were updated manually in two places, so prices drifted out of sync, and enquiries landed in one shared inbox that agents checked irregularly.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787131440475-xq7rx-c0ec4495-3721-461f-b7b0-9936fbf782e6.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTMxNDQwNDc1LXhxN3J4LWMwZWM0NDk1LTM3MjEtNDYxZi1iN2IwLTk5MzZmYmY3ODJlNi53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzMTQzOSwiZXhwIjoxOTQ0ODExNDM5fQ.TNmabk9XcHIdHzifXzwck4LDKkfoSH89gLHqn1mIiVA", "valueProp": "Listings that load fast and route to the right agent instantly.", "afterState": ["Full bilingual parity", "Fast mobile galleries", "Single listing record", "Agent-assigned enquiries"], "clientName": "Hussain Sajwani", "objectives": ["Deliver a genuinely equal Arabic and English experience", "Make listing pages fast on mobile networks", "Route every enquiry to the responsible agent immediately"], "serviceKey": "website-development", "beforeState": ["Partial Arabic site", "Slow image-heavy pages", "Duplicate listing entry", "Shared enquiry inbox"], "countryCode": "ae", "placeholder": true, "publishedDate": "2025-11-18", "challengePoints": ["Heavy mobile listing pages losing visitors before the gallery loaded", "Incomplete Arabic experience with broken right-to-left layout", "Manual listing updates and a shared, unrouted enquiry inbox"], "projectDuration": "12 weeks", "clientDescriptor": "Residential property brokerage", "shortDescription": "A brokerage site rebuilt for Arabic and English audiences, with listings that stay in sync and enquiries that reach an agent in seconds."}', '2026-08-17 14:05:37', '2026-08-19 09:24:43', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('d703591b-1e2d-4fb9-b0fd-5b2b448f01d1', 'testimonials', 'bernard-tremblay', 42, 'published', '{"id": "bernard-tremblay", "quote": "Parents ask the same questions about courses and schedules every enrolment cycle. The Messenger bot answers instantly, guides them to the right form and frees our admissions team.", "company": "Maple Leaf Academy", "location": "Vancouver, Canada", "clientName": "Bernard Tremblay", "designation": "Founder", "serviceUsed": "Facebook Automation"}', '2026-08-17 14:05:32', '2026-08-17 14:05:32', NULL);
