INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('635cad71-9ac9-4dc9-a2fd-33d428df7669', 'case_studies', 'saas-marketing-site-rebuild-usa', 0, 'published', '{"slug": "saas-marketing-site-rebuild-usa", "team": "1 strategist, 1 designer, 2 developers", "title": "Rebuilding a SaaS marketing site around buyer intent", "country": "United States", "metrics": [], "features": ["Role and use-case landing templates", "Reusable proof blocks: logos, quotes, integration cards", "In-page product tour with real screenshots", "Qualification-aware demo booking flow", "Structured data for product and FAQ pages"], "industry": "SaaS", "outcomes": ["Sales calls start at the evaluation stage instead of the explanation stage", "Marketing ships new use-case pages without engineering support", "Search traffic now lands on pages that match the query intent"], "solution": [{"title": "Use-case information architecture", "description": "New top-level journeys by role and problem, each ending in the demo path most relevant to that visitor."}, {"title": "Proof-driven page design", "description": "Comparison tables, integration detail and security answers placed where evaluators look for them."}, {"title": "Composable CMS", "description": "Marketing edits every block, publishes new pages and runs experiments without a deploy."}, {"title": "Qualified demo flow", "description": "A short qualifying form that routes fit prospects to booking and others to self-serve resources."}], "challenge": "The website described the product the way the engineering team thought about it, a long list of features. Buyers arriving from search and paid campaigns could not tell whether the product solved their specific problem, so demo requests were low-intent and sales spent calls re-explaining the basics. Content updates required a developer, so pages went stale between releases.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787131750594-pjocn-b85983cc-8e58-4081-a06c-9d85f835e692.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTMxNzUwNTk0LXBqb2NuLWI4NTk4M2NjLThlNTgtNDA4MS1hMDZjLTlkODVmODM1ZTY5Mi53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzMTc0OSwiZXhwIjoxOTQ0ODExNzQ5fQ.UIBsE4QPStohj-FfDWPiixNlQYnyq3oaN3ISDoMzGgM", "valueProp": "A site that sells to evaluators, not to the product team.", "afterState": ["Problem-led journeys", "Qualifying, routed demo flow", "Marketing-owned content", "Experiments shipped weekly"], "clientName": "Martin", "objectives": ["Rebuild the site around use cases and roles instead of features", "Let prospects self-qualify before the demo form", "Hand content control to marketing"], "serviceKey": "website-development", "beforeState": ["Feature-list homepage", "Generic demo form", "Stale content", "No page-level experimentation"], "countryCode": "us", "placeholder": true, "publishedDate": "2026-01-22", "inquiryMessage": "Hey", "challengePoints": ["Feature-led messaging that never named the buyer''s problem", "Demo requests from people who were not a fit", "Every content change blocked on engineering time"], "projectDuration": "10 weeks", "clientDescriptor": "B2B workflow software company", "shortDescription": "A feature-led SaaS site restructured into use-case journeys so evaluators could self-qualify before booking a demo."}', '2026-08-17 14:05:37', '2026-08-22 14:40:56', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('5d257590-b07a-42b0-93be-64198b18abe1', 'case_studies', 'restaurant-group-one-voice-uk', 9, 'published', '{"slug": "restaurant-group-one-voice-uk", "team": "1 strategist, 1 content designer, 1 community manager", "title": "One social voice across nine restaurant locations", "country": "United Kingdom", "metrics": [], "features": ["Group campaign calendar with per-venue slots", "Photography and caption toolkits for staff", "Complaint escalation playbook", "Local events and offers workflow", "Cross-venue performance dashboard"], "industry": "Hospitality", "outcomes": ["Group promotions now launch on the same day across every venue", "Venue teams post confidently within clear brand guardrails", "Complaints get a consistent, fast, on-brand response"], "solution": [{"title": "Hub-and-spoke content model", "description": "Group-level campaign content plus a local slot each venue fills with its own moments."}, {"title": "Shift-proof toolkit", "description": "Shot lists, caption templates and approval rules simple enough to run from a venue phone."}, {"title": "Escalation playbook", "description": "Tiered response guidance for complaints, with clear rules on what moves to private channels."}, {"title": "Group reporting", "description": "One dashboard comparing venues so head office sees performance without micromanaging."}], "challenge": "Each venue ran its own account managed by whoever was on shift. Quality swung wildly, offers were announced inconsistently, and negative reviews surfaced in comments with no agreed response. Head office had no visibility until something went wrong publicly.", "valueProp": "One brand, nine neighbourhoods, zero chaos.", "afterState": ["Shared brand standard", "Synchronised campaigns", "Playbook-driven responses", "Single reporting view"], "clientName": "[Client Name]", "objectives": ["Create one brand standard that still allows local character", "Coordinate group-wide campaigns across all venues", "Handle public complaints consistently and quickly"], "serviceKey": "social-media-marketing", "beforeState": ["Uncoordinated venue accounts", "Inconsistent offer announcements", "Ad-hoc complaint replies", "No group visibility"], "countryCode": "gb", "placeholder": true, "publishedDate": "2025-12-11", "challengePoints": ["Nine accounts with nine different standards", "Offers and events communicated inconsistently across venues", "No agreed handling for complaints in public comments"], "projectDuration": "5 months (ongoing retainer)", "clientDescriptor": "Multi-site restaurant group", "shortDescription": "Nine location accounts brought under one brand system while keeping the local personality each neighbourhood expects."}', '2026-08-17 14:05:37', '2026-08-17 14:05:37', NULL);
