INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('7d98024b-d954-4f5b-bf5e-c07e4dd92265', 'case_studies', 'd2c-skincare-content-engine-netherlands', 8, 'published', '{"slug": "d2c-skincare-content-engine-netherlands", "team": "1 strategist, 1 content designer, 1 copywriter, 1 community manager", "title": "Turning random posting into a content engine for a D2C skincare brand", "country": "Netherlands", "metrics": [], "features": ["Monthly editorial calendar with approvals", "Reusable Reels and carousel templates", "Ingredient FAQ content library", "UGC collection and rights workflow", "Monthly performance report tied to store activity"], "industry": "D2C & e-commerce", "outcomes": ["The brand looks like one brand across every post", "Ingredient questions get answered the same day, in the same voice", "Launch content is ready before the launch, not during it"], "solution": [{"title": "Content pillars", "description": "Four pillars, ingredient education, routines, customer results and behind-the-brand, mapped to buying stages."}, {"title": "Template and voice system", "description": "A modular design kit and tone guide so any team member produces on-brand work."}, {"title": "Batch production calendar", "description": "Monthly shoot-and-write batches approved in advance, ending last-minute posting."}, {"title": "Community routine", "description": "Daily comment and DM windows with saved replies for repeat ingredient questions."}], "challenge": "Posting happened whenever the founder had a spare hour, which meant bursts followed by weeks of silence. The visual identity changed post to post, ingredient questions in comments went unanswered for days, and social was never connected to what the store actually needed to sell that month.", "valueProp": "Content with a plan, a voice and a follow-up.", "afterState": ["Planned monthly calendar", "Consistent brand system", "Daily community routine", "Content aligned to launches"], "clientName": "[Client Name]", "objectives": ["Establish a repeatable content system the team can sustain", "Make the brand instantly recognisable in the feed", "Turn community activity into product discovery"], "serviceKey": "social-media-marketing", "beforeState": ["Irregular posting", "Shifting visual identity", "Slow community response", "Content disconnected from sales"], "countryCode": "nl", "placeholder": true, "publishedDate": "2026-01-30", "challengePoints": ["Inconsistent posting and visual identity", "Comments and DMs answered days late, or not at all", "No link between the content calendar and commercial priorities"], "projectDuration": "6 months (ongoing retainer)", "clientDescriptor": "Direct-to-consumer skincare brand", "shortDescription": "A skincare brand moved from ad-hoc posting to a planned content system with a recognisable voice and a real community routine."}', '2026-08-17 14:05:37', '2026-08-17 19:36:16', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('f0baf4bd-7fd4-4f4d-97fb-802cd121de37', 'case_studies', 'compliance-consultancy-visibility-usa', 10, 'published', '{"slug": "compliance-consultancy-visibility-usa", "team": "1 strategist, 1 subject-matter writer, 1 designer", "title": "Making a compliance consultancy visible without diluting its authority", "country": "United States", "metrics": [], "features": ["Recurring regulatory update series", "Partner-voice thought leadership posts", "Editorial visual system", "Two-step compliance approval workflow", "Quarterly content-to-pipeline review"], "industry": "Professional services", "outcomes": ["The firm now publishes a point of view on every major regulatory change", "Partners contribute content in an hour a month, not a weekend", "Prospects reference the firm''s posts in first meetings"], "solution": [{"title": "Expertise extraction", "description": "Monthly partner interviews mined for positions and examples, then reworked into short posts."}, {"title": "Regulatory update format", "description": "A recurring ''what changed and what to do'' series that becomes a reason to follow."}, {"title": "Restrained design language", "description": "Editorial, typography-led visuals that read as professional rather than promotional."}, {"title": "Approval workflow", "description": "A review path that respects legal sensitivity without stalling the calendar."}], "challenge": "The firm''s expertise lived in 30-page client memos. Their social presence was occasional link drops that nobody engaged with, and the partners resisted anything that felt like marketing fluff. Meanwhile, competitors with less depth were the ones being quoted in industry conversations.", "valueProp": "Serious expertise, made scrollable, without dumbing it down.", "afterState": ["Structured content supply", "Recurring signature series", "Distinct professional identity", "Partners contributing monthly"], "clientName": "[Client Name]", "objectives": ["Turn existing expertise into a repeatable content supply", "Build credibility with compliance and risk leaders", "Keep the tone appropriate for a regulated audience"], "serviceKey": "social-media-marketing", "beforeState": ["Expertise hidden in memos", "Occasional link posts", "No recognisable presence", "Partners disengaged from social"], "countryCode": "us", "placeholder": true, "publishedDate": "2025-11-25", "challengePoints": ["Deep expertise locked inside long-form client documents", "Link-drop posting with no engagement", "Partner resistance to anything that felt unserious"], "projectDuration": "6 months (ongoing retainer)", "clientDescriptor": "Regulatory compliance consultancy", "shortDescription": "Dense regulatory expertise translated into short, credible social content that compliance leaders actually stop for."}', '2026-08-17 14:05:37', '2026-08-17 19:36:16', NULL);
