INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4a601677-b0ac-48be-b2f3-12ef845bdcbb', 'case_studies', 'patient-companion-app-usa', 7, 'published', '{"slug": "patient-companion-app-usa", "team": "1 product lead, 1 designer, 2 mobile developers, 1 backend developer", "title": "A patient companion app built around appointments and follow-up care", "country": "United States", "metrics": [], "features": ["Appointment timeline with preparation checklists", "One-tap confirm, reschedule and cancel", "Post-visit care plans and medication reminders", "Secure document access", "Multi-clinic location and directions support"], "industry": "Healthcare", "outcomes": ["Patients arrive prepared for their appointment type", "Reminder confirmations arrive without staff phoning", "Follow-up instructions stay accessible after the visit"], "solution": [{"title": "Visit-aware content", "description": "Instructions generated from the appointment type, so each patient sees only their preparation steps."}, {"title": "Confirm and reschedule in-app", "description": "Reminder notifications with one-tap confirm, reschedule or cancel wired to the practice calendar."}, {"title": "Care plan follow-up", "description": "Post-visit plans, medication schedules and check-in prompts delivered on a timeline."}, {"title": "Privacy-first build", "description": "Encrypted storage, biometric access and minimised data retention with role-based staff access."}], "challenge": "Preparation instructions were printed handouts, reminders were voicemails and post-visit plans were faxed summaries. Patients arrived unprepared, appointments ran late, and staff spent mornings on reminder calls. Front-desk teams also fielded repeat calls asking what to bring and where to park.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787133991456-noc0f-df51b23f-4afc-429b-aec6-d04311e69279.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTMzOTkxNDU2LW5vYzBmLWRmNTFiMjNmLTRhZmMtNDI5Yi1hZWM2LWQwNDMxMWU2OTI3OS53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzMzk5MCwiZXhwIjoxOTQ0ODEzOTkwfQ.xv8Elj8IZSJbkzgYuVl-IubUHAhAbE5Ej_-zMWb1pbQ", "valueProp": "Care instructions patients actually receive and follow.", "afterState": ["Visit-specific digital instructions", "Confirmed appointments in-app", "Structured follow-up plans", "Fewer routine calls"], "clientName": "Luice", "objectives": ["Deliver visit-specific instructions to the patient''s phone", "Confirm attendance without a phone call", "Keep protected health information handled appropriately"], "serviceKey": "mobile-development", "beforeState": ["Printed handouts", "Voicemail reminders", "Faxed summaries", "Repetitive front-desk calls"], "countryCode": "us", "placeholder": true, "publishedDate": "2025-10-14", "challengePoints": ["Paper instructions patients lost or never read", "Voicemail reminders with no confirmation", "Staff time consumed by repetitive preparation questions"], "projectDuration": "16 weeks", "clientDescriptor": "Multi-clinic specialty practice", "shortDescription": "Appointments, preparation instructions and post-visit care plans delivered in one private app instead of paper handouts and voicemails."}', '2026-08-17 14:05:37', '2026-08-19 10:06:35', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('bbfb5db3-1ff1-47a0-a90d-293dedd32dab', 'case_studies', 'fintech-onboarding-app-singapore', 6, 'published', '{"slug": "fintech-onboarding-app-singapore", "team": "1 product lead, 1 designer, 2 mobile developers, 1 backend developer, 1 QA", "title": "A compliant onboarding flow inside a cross-platform wallet app", "country": "Singapore", "metrics": [], "features": ["Native document and liveness capture", "Step-by-step resumable onboarding", "Real-time status and required-action notifications", "Reviewer queue with audit trail", "Biometric app unlock"], "industry": "Finance & fintech", "outcomes": ["Users complete verification without leaving the app", "Support answers fewer ''where is my application'' messages", "Compliance decisions are logged with full context for audit"], "solution": [{"title": "In-app verification", "description": "Document capture, liveness and address checks embedded natively with clear retry guidance."}, {"title": "Resumable state machine", "description": "Onboarding modelled as explicit steps so users resume exactly where they stopped, on any device."}, {"title": "Compliance console", "description": "Reviewers see submissions, risk signals and audit history in one queue with decision logging."}, {"title": "Secure architecture", "description": "Encrypted local storage, certificate pinning and least-privilege API scopes throughout."}], "challenge": "Onboarding was a chain of handoffs: an app screen, a browser-based identity provider, an emailed document request and a manual review queue. Users dropped out at every jump, support handled the same status questions repeatedly, and the compliance team reviewed submissions with incomplete context.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787133846786-7j5bc-88800d55-455b-44a3-a8f1-494b0c580e8b.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTMzODQ2Nzg2LTdqNWJjLTg4ODAwZDU1LTQ1NWItNDRhMy1hOGYxLTQ5NGIwYzU4MGU4Yi53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzMzg0NSwiZXhwIjoxOTQ0ODEzODQ1fQ.hENXpdDlZ92rSx1NcommAz93PxfOBeqitFd-kt0OtDY", "valueProp": "Regulatory rigour that still feels like a consumer product.", "afterState": ["Single in-app journey", "Transparent status", "In-app document capture", "Unified reviewer console"], "clientName": "David", "objectives": ["Keep the entire onboarding journey inside the app", "Make verification status transparent to the user at all times", "Give compliance a single, complete review view"], "serviceKey": "mobile-development", "beforeState": ["Multi-channel onboarding", "Silent waiting periods", "Email document requests", "Fragmented review context"], "countryCode": "sg", "placeholder": true, "publishedDate": "2025-11-02", "challengePoints": ["Onboarding split across app, browser and email", "High abandonment at the identity verification step", "Compliance reviewing cases without complete context"], "projectDuration": "22 weeks", "clientDescriptor": "Digital payments startup", "shortDescription": "Identity verification, risk checks and account funding rebuilt into a single guided flow users can finish in one sitting."}', '2026-08-17 14:05:37', '2026-08-19 10:05:28', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('8c59b5d9-9d64-42ce-b4e4-60956461b999', 'case_studies', 'field-delivery-app-canada', 5, 'published', '{"slug": "field-delivery-app-canada", "team": "1 product lead, 1 designer, 2 mobile developers, 1 backend developer, 1 QA", "title": "A field delivery app that works without signal", "country": "Canada", "metrics": [], "features": ["Offline proof of delivery with photo and signature", "Barcode scanning and manifest reconciliation", "Background sync with conflict resolution", "Route optimisation handoff to native maps", "Exception reporting for failed deliveries"], "industry": "Logistics & transport", "outcomes": ["Drivers finish their day at the last stop, not at the depot", "Dispatch sees exceptions while the route is still running", "Delivery evidence is attached to the record automatically"], "solution": [{"title": "Offline-first data layer", "description": "Local database with a conflict-aware sync queue so scans, signatures and photos are never lost."}, {"title": "Driver-first interface", "description": "Large targets, one-handed flows and glove-friendly interactions designed for a moving workday."}, {"title": "Dispatch console", "description": "Live route progress, exception alerts and reassignment from a single operations screen."}, {"title": "Customer notifications", "description": "Automated status messages triggered by scan events, reducing inbound status calls."}], "challenge": "Drivers covered long rural routes where coverage disappears for stretches. The existing web tool required a live connection, so drivers photographed paperwork and re-entered everything at the depot at night. Dispatch had no live view of route progress and customers called the office for updates that nobody could answer.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787134040486-ftkak-d0737e11-89d1-494f-8139-fd18982abf7a.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTM0MDQwNDg2LWZ0a2FrLWQwNzM3ZTExLTg5ZDEtNDk0Zi04MTM5LWZkMTg5ODJhYmY3YS53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzNDAzOSwiZXhwIjoxOTQ0ODE0MDM5fQ.SaAL8n6km4xp24jhFANONwbNF7gTfYsq0qt-T8ZXT-M", "valueProp": "Proof of delivery that never depends on a signal bar.", "afterState": ["Full offline workflow", "Single point of capture", "Live dispatch console", "Automated customer updates"], "clientName": "Paula", "objectives": ["Make the driver workflow fully usable offline", "Eliminate evening re-entry of delivery records", "Give dispatch and customers reliable status updates"], "serviceKey": "mobile-development", "beforeState": ["Connection-dependent tool", "Paperwork re-entered nightly", "No live route view", "Manual status calls"], "countryCode": "ca", "placeholder": true, "publishedDate": "2025-12-16", "challengePoints": ["Connectivity gaps made the existing web tool unusable in the field", "Double data entry at the depot every evening", "No live route visibility for dispatch or customers"], "projectDuration": "20 weeks", "clientDescriptor": "Regional last-mile logistics operator", "shortDescription": "Drivers on rural routes get an app that captures proof of delivery offline and syncs the moment coverage returns."}', '2026-08-17 14:05:37', '2026-08-19 10:07:35', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('cf132f99-38ca-4c84-9833-fb6a7a15c6ac', 'case_studies', 'fitness-members-app-australia', 4, 'published', '{"slug": "fitness-members-app-australia", "team": "1 product lead, 1 designer, 2 mobile developers, 1 backend developer", "title": "A members app that replaced three disconnected tools", "country": "Australia", "metrics": [], "features": ["Class booking with live capacity and waitlists", "Membership, payments and pause management", "Coach messaging with programme sharing", "Push reminders for classes and expiring memberships", "Attendance check-in with QR"], "industry": "Health & fitness", "outcomes": ["Front desk time moved from admin to member experience", "Waitlist spots fill automatically instead of going empty", "The studio finally has one attendance and membership view"], "solution": [{"title": "Unified member record", "description": "A single backend joining bookings, membership status and payment history behind one identity."}, {"title": "Booking with waitlist logic", "description": "Real-time class capacity, automated waitlist promotion and cancellation windows enforced in code."}, {"title": "In-app coaching", "description": "Structured coach messaging with programme attachments, replacing personal WhatsApp threads."}, {"title": "Offline-tolerant client", "description": "Cached schedules and queued actions so the app stays usable inside gyms with poor reception."}], "challenge": "Members booked classes on one platform, managed their membership on another and messaged coaches over personal WhatsApp numbers. Front desk staff spent their day reconciling the three, cancellations were missed, and the studio had no reliable view of who was actually attending.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787134234774-k15ao-f41b94c0-9ec4-45f4-9247-29c558bbb268.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTM0MjM0Nzc0LWsxNWFvLWY0MWI5NGMwLTllYzQtNDVmNC05MjQ3LTI5YzU1OGJiYjI2OC53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzNDIzNCwiZXhwIjoxOTQ0ODE0MjM0fQ.BbYqbOVlxElF0VL7B5dZsiIoN6Ozijmr8KJfrNpb7o8", "valueProp": "One login for booking, membership and coaching.", "afterState": ["One member app", "Automated booking rules", "Clear billing states", "Coaching inside the product"], "clientName": "Tim", "objectives": ["Give members one app for everything", "Automate waitlists, cancellations and billing states", "Move coaching conversations into a supported channel"], "serviceKey": "mobile-development", "beforeState": ["Three separate platforms", "Manual reconciliation", "Missed cancellations", "Coaching on personal numbers"], "countryCode": "au", "placeholder": true, "publishedDate": "2026-01-08", "challengePoints": ["Three tools, three logins, no shared member record", "Missed cancellations and disputed billing", "Coach conversations happening on personal phones"], "projectDuration": "18 weeks", "clientDescriptor": "Boutique fitness studio group", "shortDescription": "Bookings, memberships and coach messaging brought into one cross-platform app instead of three separate logins."}', '2026-08-17 14:05:37', '2026-08-19 10:10:51', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('6cbcfcc0-8e14-4e23-b77c-7ec9d3295c29', 'case_studies', 'course-provider-enrolment-calendar-australia', 11, 'published', '{"slug": "course-provider-enrolment-calendar-australia", "team": "1 strategist, 1 content designer, 1 community manager", "title": "A course provider''s social calendar rebuilt around enrolment season", "country": "Australia", "metrics": [], "features": ["Intake-phase content calendar", "Evergreen FAQ highlight library", "Graduate outcome story series", "Deadline countdown formats", "Comment routing into admissions"], "industry": "Education & training", "outcomes": ["Prospective students find fee and eligibility answers without asking", "Deadline weeks now look and feel different from quiet weeks", "Admissions handles fewer repeat questions in comments"], "solution": [{"title": "Intake-phased calendar", "description": "Awareness, consideration and deadline phases mapped to each intake, with distinct formats per phase."}, {"title": "Answer-first content", "description": "Fees, eligibility, timetables and career outcomes turned into evergreen explainer posts and highlights."}, {"title": "Student proof series", "description": "Graduate stories and workplace footage collected on a schedule instead of chased in a panic."}, {"title": "Comment-to-enquiry routing", "description": "Saved replies with a clear path into the admissions enquiry flow."}], "challenge": "The provider posted the same course promotions all year, so campaigns competed with themselves and the weeks before each intake looked identical to the quiet months. Student questions about fees, eligibility and timetables repeated constantly in comments, and the admissions team answered each one manually.", "valueProp": "The right message at the right point in the intake cycle.", "afterState": ["Phased intake calendar", "Deadline-driven campaigns", "Evergreen answer library", "Scheduled proof collection"], "clientName": "[Client Name]", "objectives": ["Align content phases with the intake calendar", "Reduce repetitive admissions questions", "Show real student outcomes as proof"], "serviceKey": "social-media-marketing", "beforeState": ["Same message all year", "No deadline urgency", "Repetitive manual answers", "Proof collected ad hoc"], "countryCode": "au", "placeholder": true, "publishedDate": "2025-10-28", "challengePoints": ["Undifferentiated year-round promotion", "No urgency in the weeks that actually decide enrolment", "Admissions manually answering the same eligibility questions"], "projectDuration": "4 months (ongoing retainer)", "clientDescriptor": "Vocational training provider", "shortDescription": "Content re-sequenced around intake deadlines so awareness, proof and urgency arrive when prospective students are deciding."}', '2026-08-17 14:05:37', '2026-08-17 14:05:37', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('32c5ffa8-8374-439d-8c0c-945c331cd498', 'technologies', 'frontend-react', 0, 'published', '{"logo": "", "name": "React", "group": "Frontend", "description": ""}', '2026-08-18 07:11:26', '2026-08-18 07:11:26', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('1d10fd1d-3dab-40a8-b580-7bc56e8c3378', 'case_studies', 'paid-acquisition-rebuild-usa', 12, 'published', '{"slug": "paid-acquisition-rebuild-usa", "team": "1 strategist, 1 media buyer, 1 creative designer, 1 analyst", "title": "Rebuilding a paid acquisition engine around qualified leads", "country": "United States", "metrics": [], "featured": true, "features": ["Conversions API with CRM offline events", "Consolidated campaign and audience architecture", "Qualification-aware lead forms", "Structured creative testing matrix", "Looker Studio pipeline reporting"], "industry": "E-commerce & retail", "outcomes": ["Optimisation now trains on leads that sales can actually work", "Reporting connects ad spend to pipeline instead of platform metrics", "Creative decisions are based on tests, not opinions"], "solution": [{"title": "Measurement rebuild", "description": "Pixel repaired, Conversions API deployed and CRM lead status fed back as offline conversions."}, {"title": "Clean account structure", "description": "Consolidated campaigns with deduplicated audiences and disciplined exclusions."}, {"title": "Qualification in the funnel", "description": "Lead forms reworked with intent questions, filtering out contacts sales could never convert."}, {"title": "Systematic creative testing", "description": "Angle-hook-format testing matrix replacing ad-hoc creative swaps."}], "challenge": "The account looked healthy on platform metrics and terrible in the sales pipeline. Broad interest audiences overlapped, the pixel had been misconfigured for months, and lead forms were so frictionless that most submissions were unreachable. The team judged performance on cost per lead, which quietly rewarded the worst traffic.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787134880728-69jns-bdbb38b7-c27c-4c26-b0b7-9e25d9fff2d3.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTM0ODgwNzI4LTY5am5zLWJkYmIzOGI3LWMyN2MtNGMyNi1iMGI3LTllMjVkOWZmZjJkMy53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzNDg3OSwiZXhwIjoxOTQ0ODE0ODc5fQ.jkgbr6WoDNt_xhl4y2SZ51RRCOu0_leqXHFyIMDBUno", "valueProp": "Optimise for leads that close, not leads that click.", "afterState": ["Server-side tracking with CRM feedback", "Clean structure", "Sales-ready leads", "Qualified-lead cost as the KPI"], "clientName": "Iva", "objectives": ["Rebuild measurement so optimisation reflects sales reality", "Restructure audiences and creative testing", "Shift the success metric to qualified-lead cost"], "serviceKey": "meta-ads", "beforeState": ["Misconfigured tracking", "Audience overlap", "Unqualified leads", "Cost-per-lead as the only KPI"], "countryCode": "us", "placeholder": true, "publishedDate": "2026-02-02", "challengePoints": ["Broken conversion tracking feeding the algorithm bad signals", "Overlapping audiences competing in the same auctions", "Frictionless lead forms producing unqualified contacts"], "projectDuration": "5 months (ongoing retainer)", "clientDescriptor": "Home improvement retailer", "shortDescription": "Campaigns re-architected around qualified-lead cost instead of cheap clicks, with tracking rebuilt so optimisation used real sales outcomes."}', '2026-08-17 14:05:37', '2026-08-19 10:21:25', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('36b69aeb-8596-4bac-afbc-0e497d21cff5', 'case_studies', 'property-lead-quality-uae', 13, 'published', '{"slug": "property-lead-quality-uae", "team": "1 strategist, 1 media buyer, 1 creative designer", "title": "Filtering out unqualified property leads before they reach sales", "country": "United Arab Emirates", "metrics": [], "features": ["Price-led ad creative system", "Multi-step qualification forms", "Instant CRM and WhatsApp lead routing", "Agent lead-quality scoring loop", "Retargeting by qualification stage"], "industry": "Real estate", "outcomes": ["Agents spend their calling hours on buyers with realistic budgets", "Lead quality is scored weekly and fed back into targeting", "Follow-up happens while the enquiry is still warm"], "solution": [{"title": "Price-transparent creative", "description": "Starting price, payment plan and location stated in the ad so unqualified clicks stop early."}, {"title": "Multi-step qualification", "description": "Budget, timeline and purpose questions before contact details, with instant disqualification paths."}, {"title": "Speed-to-lead automation", "description": "Qualified leads pushed to CRM and WhatsApp within seconds of submission."}, {"title": "Feedback loop from sales", "description": "Weekly lead-quality scoring returned to the campaign as an optimisation signal."}], "challenge": "Campaigns produced hundreds of form fills a week, but agents estimated only a small fraction had realistic budgets. Ads promised generic ''luxury living'' with no price context, so everyone clicked. Agents burned hours calling contacts who had no intention of buying and stopped trusting the lead source entirely.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787135035405-3oo3y-0f691652-74f8-43b8-aad6-34af67c1c805.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTM1MDM1NDA1LTNvbzN5LTBmNjkxNjUyLTc0ZjgtNDNiOC1hYWQ2LTM0YWY2N2MxYzgwNS53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzNTAzNCwiZXhwIjoxOTQ0ODE1MDM0fQ.FJOrRo5egt4h7RTqNd9BPzaibqr_vekw0BCyGVgWqmM", "valueProp": "Fewer leads, better conversations.", "afterState": ["Pre-qualified pipeline", "Price-transparent ads", "Seconds-fast routing", "Sales-aligned reporting"], "clientName": "Talal Al-Nuaimi", "objectives": ["Introduce budget and timeline qualification before the form", "Make creative self-select the right buyer", "Restore sales confidence in paid channels"], "serviceKey": "meta-ads", "beforeState": ["High-volume unqualified enquiries", "Vague luxury messaging", "Slow follow-up", "Distrusted lead source"], "countryCode": "ae", "placeholder": true, "publishedDate": "2025-12-20", "challengePoints": ["Volume-driven campaigns with no budget qualification", "Generic creative attracting browsers rather than buyers", "Sales team losing trust in paid leads"], "projectDuration": "4 months (ongoing retainer)", "clientDescriptor": "Off-plan property developer", "shortDescription": "High-volume, low-intent property enquiries replaced with a pre-qualified pipeline that respects the sales team''s time."}', '2026-08-17 14:05:37', '2026-08-19 10:24:19', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4ef1d952-b797-4e6f-9754-f74dcb29c225', 'case_studies', 'consulting-founder-authority-uk', 16, 'published', '{"slug": "consulting-founder-authority-uk", "team": "1 strategist, 1 ghostwriter, 1 designer", "title": "Building inbound authority for an independent consulting founder", "country": "United Kingdom", "metrics": [], "features": ["Positioning statement and messaging guide", "Conversion-oriented profile rebuild", "Weekly post pipeline with approvals", "Comment and DM engagement routine", "Monthly inbound conversation review"], "industry": "Consulting", "outcomes": ["The founder spends one hour a week on content instead of a weekend", "Prospects arrive already agreeing with the firm''s approach", "Profile visitors have a clear next step instead of a CV"], "solution": [{"title": "Positioning and narrative", "description": "A sharp, specific position on how operations problems are actually solved, and who it is for."}, {"title": "Profile rebuild", "description": "Headline, banner, about section and featured section rewritten as a conversion path."}, {"title": "Weekly ghostwriting", "description": "Drafts sourced from real client situations, written in the founder''s voice, reviewed in one weekly slot."}, {"title": "Deliberate engagement", "description": "A daily 20-minute routine commenting where target buyers already gather."}], "challenge": "New business depended entirely on referrals and a dwindling network. The founder''s profile read like a CV, posts happened twice a year, and the genuinely valuable opinions he shared in client rooms never reached anyone else. Competitors with weaker delivery were winning on visibility alone.", "valueProp": "Stop chasing introductions. Start receiving them.", "afterState": ["Positioned, conversion-ready profile", "Weekly publishing rhythm", "Documented point of view", "Inbound conversations"], "clientName": "[Client Name]", "objectives": ["Convert profile visitors into enquiries", "Publish a consistent, defensible point of view", "Create inbound conversations with target buyers"], "serviceKey": "linkedin-personal-branding", "beforeState": ["CV-style profile", "Referral-only pipeline", "Sporadic posting", "No inbound enquiries"], "countryCode": "gb", "placeholder": true, "publishedDate": "2026-01-15", "challengePoints": ["Profile written as a CV rather than a client-facing pitch", "Pipeline entirely dependent on referrals", "Real expertise never published anywhere"], "projectDuration": "6 months (ongoing retainer)", "clientDescriptor": "Operations consultancy founder", "shortDescription": "A dormant profile turned into a consistent point of view that starts conversations with the exact buyers the firm wants."}', '2026-08-17 14:05:37', '2026-08-17 14:05:37', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('a4d9e103-82a3-4f0a-8b38-02e5a6a2aa85', 'case_studies', 'saas-founder-category-voice-usa', 17, 'published', '{"slug": "saas-founder-category-voice-usa", "team": "1 strategist, 1 ghostwriter", "title": "Giving a SaaS founder a category-defining voice", "country": "United States", "metrics": [], "features": ["Category narrative framework", "Weekly founder post pipeline", "Data-insight content series", "Repurposing workflow to newsletter and podcasts", "Audience quality review each month"], "industry": "SaaS", "outcomes": ["Sales conversations start with a shared definition of the problem", "Content doubles as recruiting and investor material", "The founder publishes consistently without it consuming the week"], "solution": [{"title": "Category narrative", "description": "A repeatable story of why the old way breaks, published in many angles before any product mention."}, {"title": "Build-in-public cadence", "description": "Product decisions, customer lessons and failures shared with specifics that peers recognise."}, {"title": "Data-led posts", "description": "Anonymised product usage patterns turned into insights only this founder could publish."}, {"title": "Distribution beyond the feed", "description": "Repurposing into newsletter, podcast pitches and community discussions."}], "challenge": "The product solved a problem most buyers had not named yet. Company-page posts about features got no traction because nobody was searching for a solution they did not know existed. Investors also expected founder visibility, and there was none.", "valueProp": "Teach the market the problem, and the product sells itself.", "afterState": ["Clear category narrative", "Problem-first content", "Visible founder presence", "Practitioner audience"], "clientName": "[Client Name]", "objectives": ["Establish the founder as the person defining the problem", "Build an audience of practitioners, not just peers", "Support fundraising and hiring with visible credibility"], "serviceKey": "linkedin-personal-branding", "beforeState": ["Unnamed problem", "Feature-led company posts", "Invisible founder", "Peer-only audience"], "countryCode": "us", "placeholder": true, "publishedDate": "2025-12-02", "challengePoints": ["Buyers had no language for the problem the product solves", "Company-page content generating no traction", "No founder presence during a fundraising cycle"], "projectDuration": "5 months (ongoing retainer)", "clientDescriptor": "Early-stage B2B SaaS founder", "shortDescription": "Founder-led content built to explain a new category, so buyers understood the problem before hearing about the product."}', '2026-08-17 14:05:37', '2026-08-17 14:05:37', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('cffa462a-0fc9-4fee-9b51-b312b7754206', 'case_studies', 'fintech-executive-visibility-singapore', 18, 'published', '{"slug": "fintech-executive-visibility-singapore", "team": "1 strategist, 1 ghostwriter, 1 compliance reviewer", "title": "Executive visibility for a fintech leader in a regulated market", "country": "Singapore", "metrics": [], "features": ["Compliance-approved content charter", "Regulatory explainer series", "Batched review and approval workflow", "Speaking and panel outreach pipeline", "Quarterly reputation review"], "industry": "Finance & fintech", "outcomes": ["Legal review takes minutes because the boundaries are pre-agreed", "The executive publishes on schedule during regulatory news cycles", "Partnership conversations now begin inbound"], "solution": [{"title": "Compliance content charter", "description": "Pre-agreed topics, claim rules and phrasing standards so most posts need only a light review."}, {"title": "Regulatory explainer series", "description": "Plain-language breakdowns of rule changes that peers and regulators can both read comfortably."}, {"title": "Two-stage review workflow", "description": "Batched drafts with a fixed weekly review slot instead of ad-hoc approvals."}, {"title": "Speaking pipeline", "description": "Content mapped to conference themes to convert visibility into stage invitations."}], "challenge": "The executive was expected to represent the company publicly, but every draft died in legal review. Without a defined boundary of what could be said, the safest answer was always to publish nothing. Conference invitations and partnership conversations went to more visible competitors.", "valueProp": "A public voice that legal is comfortable with.", "afterState": ["Charter-driven approvals", "Predictable publishing", "Recognised regulatory voice", "Active speaking pipeline"], "clientName": "[Client Name]", "objectives": ["Create a compliant, predictable publishing process", "Build recognised expertise in payments and regulation", "Turn visibility into partnership conversations"], "serviceKey": "linkedin-personal-branding", "beforeState": ["Drafts stuck in legal", "No publishing boundaries", "Silent executive presence", "Missed speaking opportunities"], "countryCode": "sg", "placeholder": true, "publishedDate": "2025-11-12", "challengePoints": ["Every draft stalled in unstructured legal review", "No agreed boundaries for public commentary", "Visibility opportunities going to competitors"], "projectDuration": "6 months (ongoing retainer)", "clientDescriptor": "Fintech C-suite executive", "shortDescription": "A compliant publishing system that let a regulated-industry executive speak publicly without creating legal exposure."}', '2026-08-17 14:05:37', '2026-08-17 14:05:37', NULL);
