INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('f712c06a-926f-4a0a-aebf-c25cc775a5af', 'case_studies', 'saas-support-deflection-germany', 20, 'published', '{"slug": "saas-support-deflection-germany", "team": "1 AI engineer, 1 conversation designer, 1 backend developer", "title": "A support assistant that answers product questions instead of deflecting them", "country": "Germany", "metrics": [], "features": ["Retrieval-grounded answers with citations", "Confidence-based human escalation", "German/English support with glossary control", "Helpdesk integration with full transcript handoff", "Unanswered-question reporting"], "industry": "SaaS", "outcomes": ["Routine product questions are answered instantly, with sources", "Escalations arrive with the full conversation, not a fresh start", "Documentation gaps surface as data instead of complaints"], "solution": [{"title": "Grounded retrieval", "description": "Answers generated only from indexed, approved documentation with source links shown to the user."}, {"title": "Confidence-based escalation", "description": "Low-confidence or policy-sensitive questions routed to a human with the conversation attached."}, {"title": "Multilingual handling", "description": "German and English handled natively, with terminology consistency enforced by a glossary."}, {"title": "Answer quality loop", "description": "Weekly review of unanswered and corrected questions feeding documentation improvements."}], "challenge": "The support team handled a large share of tickets that were already answered in the documentation, but customers could not find them. A previous rule-based bot frustrated users with canned replies and was switched off. Support response times slipped during European business hours, and complex tickets waited behind simple ones.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787116536406-c42pm-6dc6a27a-1c5f-44c5-9fa9-0779d029d3bc.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTE2NTM2NDA2LWM0MnBtLTZkYzZhMjdhLTFjNWYtNDRjNS05ZmE5LTA3NzlkMDI5ZDNiYy53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzExNjUzNSwiZXhwIjoxOTQ0Nzk2NTM1fQ.kuh-evKtw8EccywUt9PHmTgfRoy-JT3xEZ5s8tqFxKE", "valueProp": "Real answers, grounded in your documentation.", "afterState": ["Grounded self-service", "Context-rich escalation", "Agents focused on complex work", "Documentation gaps reported weekly"], "clientName": "Felix", "objectives": ["Resolve routine questions accurately and immediately", "Escalate genuinely complex issues with full context", "Never answer outside approved documentation"], "serviceKey": "chatbot-solutions", "beforeState": ["Repetitive tickets", "Canned-reply bot", "Slow complex-ticket response", "Documentation gaps invisible"], "countryCode": "de", "placeholder": true, "publishedDate": "2026-01-26", "challengePoints": ["Documented answers customers could not find", "An earlier rule-based bot that users actively avoided", "Complex tickets queued behind repetitive ones"], "projectDuration": "10 weeks", "clientDescriptor": "B2B SaaS platform", "shortDescription": "A grounded AI assistant trained on approved documentation that resolves routine product questions and escalates the rest with context."}', '2026-08-17 14:05:37', '2026-08-19 05:16:19', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('b57f8610-fe50-496f-afc8-7b721b195fda', 'case_studies', 'insurance-policy-assistant-uk', 22, 'published', '{"slug": "insurance-policy-assistant-uk", "team": "1 AI engineer, 1 conversation designer, 1 compliance reviewer, 1 developer", "title": "A policy assistant that explains cover without giving advice", "country": "United Kingdom", "metrics": [], "features": ["Clause-cited policy explanations", "Advice-intent detection and refusal handling", "Claims and complaints routing", "Full conversation audit log", "Compliance review dashboard"], "industry": "Insurance", "outcomes": ["Customers get plain-English explanations with the clause referenced", "Advice conversations reach a qualified human by design", "Compliance can audit every answer the assistant gave"], "solution": [{"title": "Boundaried answer scope", "description": "The assistant explains documented policy wording only, with explicit refusal patterns for advice questions."}, {"title": "Intent classification", "description": "Advice-seeking, complaint and claim intents detected and routed to the correct human team immediately."}, {"title": "Full auditability", "description": "Every conversation logged with the source clause used, retained for compliance review."}, {"title": "Reviewed rollout", "description": "A supervised pilot where compliance reviewed transcripts daily before scope was widened."}], "challenge": "Customers phoned to ask what their policy covered, and advisers spent their day reading documents aloud. Automating this was risky: anything resembling advice creates regulatory exposure. Previous attempts were abandoned because compliance could not accept an unpredictable answer generator.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787120278132-iunmi-7b214a8b-a504-43b6-9964-180b5fee69cf.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTIwMjc4MTMyLWl1bm1pLTdiMjE0YThiLWE1MDQtNDNiNi05OTY0LTE4MGI1ZmVlNjljZi53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyMDI3NywiZXhwIjoxOTQ0ODAwMjc3fQ.OKe05OzyYYiTHx_ViXW0jK8lxzy17BXV_COLLPfTqsQ", "valueProp": "Clarity for customers, guardrails for compliance.", "afterState": ["Self-service policy explanations", "Advisers on advice work", "Compliance-approved scope", "Fully auditable conversations"], "clientName": "Noah", "objectives": ["Explain existing cover clearly and accurately", "Never cross into regulated advice", "Route advice-seeking customers to a qualified adviser"], "serviceKey": "chatbot-solutions", "beforeState": ["Advisers reading documents aloud", "Long call queues", "No safe automation", "No conversation audit trail"], "countryCode": "gb", "placeholder": true, "publishedDate": "2025-11-05", "challengePoints": ["Advisers reading policy wording aloud all day", "Regulatory risk around anything resembling advice", "Earlier automation attempts rejected by compliance"], "projectDuration": "12 weeks", "clientDescriptor": "Insurance brokerage", "shortDescription": "Policy wording questions answered in plain English inside strict regulatory boundaries, with advice-seeking conversations routed to advisers."}', '2026-08-17 14:05:37', '2026-08-19 06:18:05', NULL);
