INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('ab83bfbd-0498-4bd5-814f-2ea67fc48136', 'case_studies', 'logistics-tracking-assistant-singapore', 23, 'published', '{"slug": "logistics-tracking-assistant-singapore", "team": "1 AI engineer, 1 conversation designer, 1 integration developer", "title": "A shipment assistant that ends the ''where is my order'' queue", "country": "Singapore", "metrics": [], "features": ["Multi-carrier shipment status lookup", "Standardised delay explanations", "Authenticated document retrieval", "Proactive milestone alerts", "Escalation to the assigned operations owner"], "industry": "Logistics & freight", "outcomes": ["Clients check shipment status themselves, at any hour", "Delay explanations are consistent regardless of who is on shift", "Operations handles exceptions instead of lookups"], "solution": [{"title": "Carrier data integration", "description": "Live milestone data pulled from carrier and port systems into a single status view."}, {"title": "Explained exceptions", "description": "Standardised, accurate explanations for common delay causes, with expected next milestone."}, {"title": "Secure document retrieval", "description": "Authenticated access to bills of lading, invoices and customs paperwork inside the chat."}, {"title": "Proactive alerts", "description": "Milestone and exception notifications sent before the client thinks to ask."}], "challenge": "Clients across many time zones emailed for shipment status at all hours. Operations staff manually checked carrier portals and replied, often hours later. Delay explanations were inconsistent depending on who answered, and document requests interrupted the same team that managed live shipments.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787121832267-1042a-295a80d8-650c-4c5b-8437-de16aae343fa.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTIxODMyMjY3LTEwNDJhLTI5NWE4MGQ4LTY1MGMtNGM1Yi04NDM3LWRlMTZhYWUzNDNmYS53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyMTgzMSwiZXhwIjoxOTQ0ODAxODMxfQ.wdJHACvk4vfpiXCu8ugs5ilDZYkATsFSph_SX2aRIQQ", "valueProp": "Shipment answers at 3am, without waking operations.", "afterState": ["Self-service tracking", "Instant answers in every time zone", "Standardised messaging", "Operations focused on exceptions"], "clientName": "Edwin", "objectives": ["Give clients self-service shipment visibility", "Standardise how delays are explained", "Free operations from routine lookups"], "serviceKey": "chatbot-solutions", "beforeState": ["Manual portal checks", "Delayed replies across time zones", "Inconsistent explanations", "Interrupted operations team"], "countryCode": "sg", "placeholder": true, "publishedDate": "2025-10-02", "challengePoints": ["Round-the-clock status requests handled manually", "Inconsistent delay explanations between staff", "Document requests interrupting live operations work"], "projectDuration": "9 weeks", "clientDescriptor": "Freight forwarding company", "shortDescription": "Live shipment status, documentation and delay explanations delivered to clients across time zones without an operations handoff."}', '2026-08-17 14:05:37', '2026-08-19 06:44:09', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('912b2fa4-d099-40ec-92e5-605aa4b3bd68', 'case_studies', 'trades-quote-automation-australia', 25, 'published', '{"slug": "trades-quote-automation-australia", "team": "1 automation engineer, 1 conversation designer", "title": "Quote request automation for a trades services business", "country": "Australia", "metrics": [], "features": ["Photo and location capture in chat", "Emergency vs routine triage routing", "Automated quote delivery and acceptance", "Appointment confirmation and reminders", "Job management system sync"], "industry": "Home services", "outcomes": ["Customers get an immediate response while technicians stay on the tools", "Most jobs can be quoted from photos and job details alone", "Emergency work reaches the on-call technician straight away"], "solution": [{"title": "Instant structured intake", "description": "An automated flow collecting job type, urgency, photos, address and access notes within minutes."}, {"title": "Urgency triage", "description": "Emergency jobs flagged and pushed to the on-call technician; routine jobs queued for scheduling."}, {"title": "Quote delivery in chat", "description": "Quotes sent and accepted in the same thread, with a booking confirmation."}, {"title": "Job-record sync", "description": "Every enquiry, photo and approval logged into the job management system automatically."}], "challenge": "Technicians were on jobs all day and returned calls at night, by which time customers had booked someone else. Quote requests arrived with no photos, no address and no sense of urgency, so every job needed a call and often a wasted site visit to scope.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787122583857-oalcq-20c141fb-aceb-47df-b00a-1324729d50a0.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTIyNTgzODU3LW9hbGNxLTIwYzE0MWZiLWFjZWItNDdkZi1iMDBhLTEzMjQ3MjlkNTBhMC53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyMjU4MywiZXhwIjoxOTQ0ODAyNTgzfQ.QsGuqF1M7KUwLgm-nPgKIj2Iiej6jKuKjvV7QAdLeA8", "valueProp": "Everything needed to quote, collected before anyone calls back.", "afterState": ["Immediate automated response", "Complete intake with photos", "Remote quoting", "Same-day quote turnaround"], "clientName": "Houlman", "objectives": ["Respond to every enquiry immediately, even mid-job", "Collect complete job information up front", "Reduce unnecessary scoping visits"], "serviceKey": "whatsapp-automation", "beforeState": ["Late-night callbacks", "Incomplete job information", "Scoping site visits", "Lost jobs to faster competitors"], "countryCode": "au", "placeholder": true, "publishedDate": "2025-12-14", "challengePoints": ["Callbacks happening hours after the customer moved on", "Quote requests missing photos, location and job detail", "Wasted site visits just to understand the job"], "projectDuration": "6 weeks", "clientDescriptor": "Electrical and HVAC services company", "shortDescription": "Job details, photos and location collected automatically over WhatsApp so technicians quote accurately without a site visit."}', '2026-08-17 14:05:37', '2026-08-19 06:56:31', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('b7767950-e305-43c3-b1c9-a56e026b4671', 'case_studies', 'admissions-followup-automation-usa', 26, 'published', '{"slug": "admissions-followup-automation-usa", "team": "1 automation engineer, 1 conversation designer, 1 integration developer", "title": "Admissions follow-up automation that stops enquiries going cold", "country": "United States", "metrics": [], "features": ["Application-stage triggered messaging", "In-chat document upload and validation", "Deadline reminder sequences", "Counsellor assignment and handover", "Admissions pipeline dashboard"], "industry": "Education", "outcomes": ["Every applicant receives the same quality of follow-up, peak season included", "Missing documents are chased automatically before the deadline", "Counsellors know exactly who is stuck and why"], "solution": [{"title": "Stage-aware sequences", "description": "Follow-up messages triggered by application stage rather than by a fixed schedule."}, {"title": "Document collection in chat", "description": "Applicants upload required documents in WhatsApp, validated and filed automatically."}, {"title": "Counsellor handover", "description": "Complex questions routed to the assigned counsellor with the applicant''s full history."}, {"title": "Pipeline visibility", "description": "A live board showing every applicant''s current stage and blocking item."}], "challenge": "Enquiries arrived in bursts around intake deadlines. The admissions team could not follow up consistently, so applications stalled halfway through with documents missing. Email reminders went unread, and no one knew which applicants were stuck at which step.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787122632623-smv9o-c4629f9d-e3aa-47bd-b72e-7e212e798841.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTIyNjMyNjIzLXNtdjlvLWM0NjI5ZjlkLWUzYWEtNDdiZC1iNzJlLTdlMjEyZTc5ODg0MS53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyMjYzMiwiZXhwIjoxOTQ0ODAyNjMyfQ._Uxt_CBouoUG1R3h1oU4GFkfsPYxo-yZ0SRXfP893hU", "valueProp": "Follow-up that keeps pace with applicant intent.", "afterState": ["Automated stage-based nurture", "Guided document submission", "High-visibility WhatsApp reminders", "Live pipeline board"], "clientName": "Juan Jose", "objectives": ["Maintain consistent follow-up regardless of volume", "Help applicants complete each step on time", "Give admissions a live view of where applicants are stuck"], "serviceKey": "whatsapp-automation", "beforeState": ["Inconsistent peak-season follow-up", "Half-finished applications", "Unread email reminders", "No stage visibility"], "countryCode": "us", "placeholder": true, "publishedDate": "2025-11-20", "challengePoints": ["Follow-up capacity collapsing during peak intake weeks", "Applications abandoned midway with missing documents", "Email reminders largely unread"], "projectDuration": "7 weeks", "clientDescriptor": "Private education institution", "shortDescription": "Prospective students guided from first question to completed application with timely, personalised WhatsApp follow-up."}', '2026-08-17 14:05:37', '2026-08-19 06:57:20', NULL);
