INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('ecd53cc3-773d-4ed8-956c-4c3f7ac45c6e', 'case_studies', 'travel-booking-support-uk', 27, 'published', '{"slug": "travel-booking-support-uk", "team": "1 automation engineer, 1 conversation designer, 1 integration developer", "title": "Travel booking support automation across time zones", "country": "United Kingdom", "metrics": [], "features": ["Booking-linked itinerary answers", "Emergency escalation to on-call staff", "On-demand travel document retrieval", "Timed pre-departure and in-trip messages", "Post-trip feedback collection"], "industry": "Travel & tourism", "outcomes": ["Travellers get itinerary answers instantly, wherever they are", "Genuine emergencies reach a human immediately, day or night", "The team stops monitoring the inbox for routine questions"], "solution": [{"title": "Itinerary-aware assistant", "description": "Booking data connected so answers reference the traveller''s actual schedule and location."}, {"title": "Emergency detection", "description": "Urgency and distress signals trigger immediate escalation to the on-call consultant with full context."}, {"title": "Document vault in chat", "description": "Vouchers, tickets and insurance documents retrievable on demand."}, {"title": "Pre-departure and in-trip sequences", "description": "Timed messages for check-in, transfers and local guidance."}], "challenge": "Customers travelling abroad messaged at every hour asking for itinerary details, transfer times and documents they had lost in their inbox. Routine requests were mixed with genuine emergencies, and the small team could not distinguish them quickly enough during the night.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787123193100-oh21g-bb90c648-4550-4efa-9be9-21027198fd04.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTIzMTkzMTAwLW9oMjFnLWJiOTBjNjQ4LTQ1NTAtNGVmYS05YmU5LTIxMDI3MTk4ZmQwNC53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyMzE5MywiZXhwIjoxOTQ0ODAzMTkzfQ.-Yz_c-DmPYOVXwrgHAKSGi6D2E3w2NatXgbFvRGEcp4", "valueProp": "In-trip support that never depends on office hours.", "afterState": ["Automated routine support", "Prioritised emergency escalation", "Instant document access", "Structured trip communications"], "clientName": "Laura", "objectives": ["Serve routine in-trip requests automatically at any hour", "Identify and escalate genuine emergencies immediately", "Keep travel documents one message away"], "serviceKey": "whatsapp-automation", "beforeState": ["24/7 manual monitoring", "Emergencies lost in routine messages", "Documents hard to find", "Inconsistent in-trip contact"], "countryCode": "gb", "placeholder": true, "publishedDate": "2025-10-10", "challengePoints": ["Round-the-clock in-trip messages from multiple time zones", "Routine requests indistinguishable from emergencies", "Documents buried in customer email inboxes"], "projectDuration": "8 weeks", "clientDescriptor": "Boutique travel operator", "shortDescription": "Travelling customers get itinerary details, documents and urgent help on WhatsApp, with real emergencies reaching a human fast."}', '2026-08-17 14:05:37', '2026-08-19 07:06:36', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('6b4fa46c-5028-43c0-8a94-eebfa43b6171', 'case_studies', 'fashion-comment-to-dm-usa', 28, 'published', '{"slug": "fashion-comment-to-dm-usa", "team": "1 automation engineer, 1 conversation designer, 1 social strategist", "title": "Turning comments into conversations for a fashion D2C brand", "country": "United States", "metrics": [], "features": ["Comment intent detection and auto-reply", "Product-specific DM flows with checkout links", "Restock and waitlist capture", "Complaint escalation to human agents", "Campaign-specific automation templates"], "industry": "D2C & fashion", "outcomes": ["Purchase questions are answered while the post is still active", "Interested buyers receive a checkout link in DM automatically", "The social team handles genuine issues instead of repetitive questions"], "solution": [{"title": "Intent-triggered replies", "description": "Keyword and intent detection on comments triggers a brand-voice public reply plus a DM with detail."}, {"title": "Product-aware DM flows", "description": "DMs carry the specific product, live sizing availability and a direct checkout link."}, {"title": "Human escalation rules", "description": "Complaints, sizing disputes and order issues bypass automation and reach a person."}, {"title": "Campaign-linked automations", "description": "Launch posts get dedicated flows for waitlists and restock alerts."}], "challenge": "Popular posts collected hundreds of comments asking price, size availability and shipping. The two-person social team answered a fraction, usually a day later. Interested buyers moved on, and the unanswered comments made the brand look inattentive to everyone else reading.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787125513112-20ktd-4f716116-2aea-4d71-81d7-ca9230f435d7.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTI1NTEzMTEyLTIwa3RkLTRmNzE2MTE2LTJhZWEtNGQ3MS04MWQ3LWNhOTIzMGY0MzVkNy53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyNTUxMiwiZXhwIjoxOTQ0ODA1NTEyfQ.kSlWrI8h0JGThOsZ_SploiwG9UcuhV8-RHG9nwlfQVA", "valueProp": "Every comment answered while the shopper is still scrolling.", "afterState": ["Seconds-fast public replies", "Product-aware DM journeys", "Captured demand via waitlists", "Team focused on real issues"], "clientName": "Fad\\u00e9 Adeniyi", "objectives": ["Reply to every purchase-intent comment quickly", "Move buying conversations into DMs", "Keep the brand voice intact in automated replies"], "serviceKey": "facebook-automation", "beforeState": ["Unanswered comment threads", "Day-late replies", "Lost purchase intent", "Overloaded two-person team"], "countryCode": "us", "placeholder": true, "publishedDate": "2026-01-19", "challengePoints": ["Hundreds of purchase-intent comments left unanswered", "Replies arriving a day after the moment of interest", "Public silence damaging brand perception"], "projectDuration": "6 weeks", "clientDescriptor": "Direct-to-consumer fashion label", "shortDescription": "Comment and DM automation that answers sizing and availability questions in seconds and moves buyers to checkout."}', '2026-08-17 14:05:37', '2026-08-19 07:47:00', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('039a3069-992f-4d78-8297-3f2a08039551', 'case_studies', 'gym-lead-capture-uk', 30, 'published', '{"slug": "gym-lead-capture-uk", "team": "1 automation engineer, 1 conversation designer", "title": "Automated lead capture for a gym group''s social channels", "country": "United Kingdom", "metrics": [], "features": ["Multi-page unified message automation", "Postcode-based club routing", "Automated trial pass delivery", "Consistent pricing responses", "Campaign surge flows"], "industry": "Health & fitness", "outcomes": ["No enquiry sits unread because no one owns the page", "Every prospect hears the same, correct pricing", "Promotions can run without the inbox becoming a bottleneck"], "solution": [{"title": "Unified inbox automation", "description": "All pages funnelled into one automated intake with consistent, approved answers."}, {"title": "Location-based routing", "description": "Postcode capture assigns each lead to the nearest club and its membership team."}, {"title": "Trial pass automation", "description": "Instant trial pass issuance with a booking link and reminder sequence."}, {"title": "Promotion surge handling", "description": "Campaign-specific flows that absorb message spikes without extra staffing."}], "challenge": "Enquiries about membership prices and trial passes arrived across a group page and several club-level pages. Nobody owned the reply, so messages sat unread for days or were answered twice with different prices. Promotions drove message spikes the team could not absorb.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787125783411-lmz6g-a5fe1a3b-dd31-4484-b741-e1a5bb1b65e3.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTI1NzgzNDExLWxtejZnLWE1ZmUxYTNiLWRkMzEtNDQ4NC1iNzQxLWUxYTViYjFiNjVlMy53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyNTc4MywiZXhwIjoxOTQ0ODA1NzgzfQ.EQSTO3ftapvkOXGPSEyYMyHkEDOiiZ5h_QwMuUrYbew", "valueProp": "Enquiries routed to the right club, in seconds.", "afterState": ["Single automated intake", "Approved consistent answers", "Instant routing to the nearest club", "Campaign-ready capacity"], "clientName": "Mario", "objectives": ["Capture every enquiry regardless of which page it lands on", "Answer price and trial questions consistently", "Route each lead to the nearest club with a clear owner"], "serviceKey": "facebook-automation", "beforeState": ["Unowned enquiries", "Conflicting pricing answers", "Days-long response times", "Promotions creating backlogs"], "countryCode": "gb", "placeholder": true, "publishedDate": "2025-11-15", "challengePoints": ["Enquiries spread across group and club-level pages with no owner", "Conflicting price answers from different staff", "Promotion spikes overwhelming manual replies"], "projectDuration": "5 weeks", "clientDescriptor": "Multi-site gym group", "shortDescription": "Membership questions on Facebook and Instagram captured, qualified by location and routed to the right club instantly."}', '2026-08-17 14:05:37', '2026-08-19 07:50:00', NULL);
