INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('09cd91e8-2473-4015-9f95-a7571607058e', 'case_studies', 'healthcare-scheduling-voice-bot-usa', 33, 'published', '{"slug": "healthcare-scheduling-voice-bot-usa", "team": "1 AI engineer, 1 conversation designer, 1 telephony engineer, 1 integration developer", "title": "Voice scheduling that clears the morning phone queue", "country": "United States", "metrics": [], "features": ["Live-availability appointment booking by phone", "Reschedule and cancellation handling", "Clinical call transfer rules", "English and Spanish support", "Call transcript logging to the practice system"], "industry": "Healthcare", "outcomes": ["Routine booking calls no longer wait behind the waiting-room queue", "Clinical questions reach staff immediately by design", "Patients can book by phone outside opening hours"], "solution": [{"title": "Scheduling-capable voice assistant", "description": "Booking, rescheduling and cancellation completed on the call against live clinic availability."}, {"title": "Clear triage boundaries", "description": "Symptom, prescription and clinical calls transferred to staff immediately, never handled by AI."}, {"title": "Multilingual coverage", "description": "English and Spanish handled natively with consistent scheduling logic."}, {"title": "Privacy-conscious design", "description": "Minimal data collection, verified identity before any record access, full call logging."}], "challenge": "The phone queue peaked the moment the clinics opened. Staff juggled ringing phones and a waiting-room line, callers waited on hold and many gave up. Most of those calls were routine: booking, rescheduling, opening hours and directions.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787124953297-nwxur-028e6673-ed6a-48bc-9c40-bcb789db1bfe.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTI0OTUzMjk3LW53eHVyLTAyOGU2NjczLWVkNmEtNDhiYy05YzQwLWJjYjc4OWRiMWJmZS53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyNDk1MiwiZXhwIjoxOTQ0ODA0OTUyfQ.Hyy6z_4VobrvdYYpzeW-SJY4aiRWXlm2vEFRa_HvDLE", "valueProp": "Phones answered on the first ring, every morning.", "afterState": ["Calls answered instantly", "Routine scheduling automated", "Clinical calls prioritised", "Staff focused on in-clinic patients"], "clientName": "Philip Aguib", "objectives": ["Handle routine scheduling calls without a human", "Eliminate hold times for common requests", "Keep clinical and sensitive calls with staff"], "serviceKey": "voice-bot-solutions", "beforeState": ["Opening-hour call queues", "Long hold times", "Abandoned calls", "Divided front-desk attention"], "countryCode": "us", "placeholder": true, "publishedDate": "2025-12-18", "challengePoints": ["Severe call queues at opening hours", "Front-desk staff split between phones and the waiting room", "High call abandonment on hold"], "projectDuration": "12 weeks", "clientDescriptor": "Primary care clinic network", "shortDescription": "Routine appointment calls handled by a voice assistant so front-desk staff can care for the patients standing in front of them."}', '2026-08-17 14:05:37', '2026-08-19 07:35:56', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4131dedc-f14d-491d-ba76-d8ff1cd347e6', 'case_studies', 'events-ticketing-automation-netherlands', 31, 'published', '{"slug": "events-ticketing-automation-netherlands", "team": "1 automation engineer, 1 conversation designer, 1 social strategist", "title": "Ticketing and attendee support automation for an events company", "country": "Netherlands", "metrics": [], "features": ["Per-event knowledge configuration", "Ticket issue triage and escalation", "Live event-day response mode", "Accessibility information flows", "Post-event feedback and remarketing capture"], "industry": "Events & entertainment", "outcomes": ["Attendees get event details instantly, including during the event", "Ticket problems reach the ticketing team with the order attached", "The team stops hiring temporary staff for message volume"], "solution": [{"title": "Event knowledge automation", "description": "Timings, entry rules, accessibility and transport answers maintained per event and served instantly."}, {"title": "Ticket support triage", "description": "Transfer, refund and access problems escalated to the ticketing team with the order reference."}, {"title": "Live event mode", "description": "A day-of configuration answering on-site questions with real-time updates."}, {"title": "Post-event follow-up", "description": "Feedback collection and early access offers for the next event."}], "challenge": "In the week before each event, message volume multiplied. Attendees asked the same questions about timings, entry rules, accessibility and ticket transfers. The team hired temporary staff to reply manually and still missed messages during the event itself, when answers mattered most.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787125358023-7fsg9-2997edec-f42c-4930-b00f-96aa694a49c0.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTI1MzU4MDIzLTdmc2c5LTI5OTdlZGVjLWY0MmMtNDkzMC1iMDBmLTk2YWE2OTRhNDljMC53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyNTM1NywiZXhwIjoxOTQ0ODA1MzU3fQ.59KvAj6L2Ns_htrIIs0YB-MJciEil8w15nsq3A5EPQ8", "valueProp": "Event-week message volume, handled without extra staff.", "afterState": ["Automated peak coverage", "No temporary staffing needed", "Live on-the-day responses", "Consistent event information"], "clientName": "Joel Spenner", "objectives": ["Handle event-week volume without temporary staffing", "Answer operational questions instantly and accurately", "Keep genuine ticket problems reaching a human"], "serviceKey": "facebook-automation", "beforeState": ["Event-week message backlog", "Temporary staff costs", "Missed messages during events", "Inconsistent operational answers"], "countryCode": "nl", "placeholder": true, "publishedDate": "2025-10-24", "challengePoints": ["Extreme message spikes in the final week before events", "The same operational questions repeated hundreds of times", "Temporary staffing that was expensive and still insufficient"], "projectDuration": "6 weeks", "clientDescriptor": "Live events and festival organiser", "shortDescription": "Ticket, timing and access questions answered automatically through event week, when message volume peaks hardest."}', '2026-08-17 14:05:37', '2026-08-19 07:43:07', NULL);
