INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('ca93a5db-fdab-4e72-8ccb-a3bc7c49ce9f', 'case_studies', 'ecommerce-experience-rebuild-uk', 1, 'published', '{"slug": "ecommerce-experience-rebuild-uk", "team": "1 strategist, 1 UX designer, 2 developers, 1 QA", "title": "Turning a fragmented digital experience into a high-converting customer journey", "country": "United Kingdom", "metrics": [], "featured": true, "features": ["Headless storefront with component design system", "Editable campaign landing pages without developer involvement", "Faceted search and filtering on category pages", "Single-page checkout with saved addresses", "Server-side event tracking into GA4 and the ad platforms"], "industry": "E-commerce", "outcomes": ["Marketing can launch a campaign landing page in hours instead of a sprint", "Support tickets caused by conflicting product information stopped", "The team can finally see which step of the funnel loses customers"], "solution": [{"title": "Unified storefront architecture", "description": "Campaign pages, catalogue and content moved onto one headless front end sharing a single product source of truth."}, {"title": "Conversion-first templates", "description": "Category, product and checkout templates rebuilt around the decisions shoppers actually make, with persistent cart and trust signals."}, {"title": "Performance engineering", "description": "Image pipeline, code splitting and edge caching brought Core Web Vitals into the green on mid-range mobile devices."}, {"title": "Clean measurement layer", "description": "One analytics property with server-side events, so every step from ad click to order is attributable."}], "challenge": "The brand had grown by bolting on platforms: a legacy storefront, a separate campaign microsite and a blog on a third system. Customers arriving from ads landed on pages that looked and behaved differently, product data disagreed between systems, and mobile pages took several seconds to become usable. Nobody could say where the drop-off happened because analytics was split across three properties.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787131619996-mpr6r-47e92a5b-791c-466e-984d-4af13bced169.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTMxNjE5OTk2LW1wcjZyLTQ3ZTkyYTViLTc5MWMtNDY2ZS05ODRkLTRhZjEzYmNlZDE2OS53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzMTYxOCwiZXhwIjoxOTQ0ODExNjE4fQ.wm_4D5S0XX1xW5iVFezI-RK0sgzgtCy94e_gFopQ3f8", "valueProp": "One storefront, one journey, one measurable funnel.", "afterState": ["One platform with a shared design system", "Single product source of truth", "Fast, stable mobile experience", "One end-to-end funnel dashboard"], "clientName": "Shawn", "objectives": ["Consolidate every customer touchpoint into one platform and one design system", "Make category-to-checkout the fastest path on mobile", "Give the marketing team a single, trustworthy funnel view"], "serviceKey": "website-development", "beforeState": ["Three platforms, three design languages", "Product data edited in multiple places", "Slow mobile pages", "Funnel reporting stitched together manually"], "countryCode": "gb", "placeholder": true, "publishedDate": "2026-02-10", "challengePoints": ["Three separate front ends with inconsistent design, navigation and product data", "Slow mobile pages, especially on category and product templates", "Fragmented analytics made funnel drop-off impossible to diagnose"], "projectDuration": "14 weeks", "clientDescriptor": "Multi-category online retailer", "shortDescription": "A retailer running three disconnected front ends rebuilt as one fast, coherent shopping journey from ad click to checkout."}', '2026-08-17 14:05:37', '2026-08-19 09:27:02', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('affaeb9d-736b-47dc-b4db-2893a8e5c8c7', 'services', 'website-development', 0, 'published', '{"h1": "Website Development That Wins Trust and Generates Inquiries", "faqs": [{"answer": "It includes discovery and strategy, information architecture, UI design, frontend and backend development, CMS setup, integrations, SEO and AEO implementation, performance optimisation, testing, launch and post-launch support.", "question": "What does website development include?"}, {"answer": "A focused landing page typically takes 1\\u20132 weeks. A business website usually takes 3\\u20136 weeks. Web applications, e-commerce and SaaS platforms depend on scope and are planned in phases after discovery.", "question": "How long does it take to build a website?"}, {"answer": "Frontend work uses React, Next.js, Angular, TypeScript, HTML and CSS. Backend work uses Node.js, .NET, ASP.NET Core, C#, Python and REST APIs. Databases include SQL Server, PostgreSQL, MySQL, MongoDB and Supabase.", "question": "Which technologies do you use for website development?"}, {"answer": "Yes. Every build starts from your brand, audience and commercial goals. We do not resell themes, we build a design system and component library specific to your business.", "question": "Can you build fully custom websites?"}, {"answer": "Yes. We regularly integrate CRMs, payment gateways, email platforms, analytics, booking systems, ERPs and internal APIs, including secure server-side integrations.", "question": "Can you integrate third-party APIs and CRMs?"}, {"answer": "Yes. Unique metadata, semantic headings, canonical URLs, sitemap, robots rules, structured data, image alt text, internal linking and Core Web Vitals optimisation are part of the build.", "question": "Will the website be SEO friendly?"}], "name": "Website Development", "slug": "website-development", "image": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787041633386-aeykp-website-development.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MDQxNjMzMzg2LWFleWtwLXdlYnNpdGUtZGV2ZWxvcG1lbnQud2VicCIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODcwNDE2MzIsImV4cCI6MTk0NDcyMTYzMn0.FBxlIHT929HJdlfqiT3UrdBbeVDWC4SwEixSu6CXTJg", "steps": [{"title": "Discovery", "description": "Goals, audience, competitors and current performance."}, {"title": "Architecture", "description": "Sitemap, page intent, keyword and content mapping."}, {"title": "Design", "description": "Design system, wireframes and premium high-fidelity UI."}, {"title": "Development", "description": "Frontend, backend, integrations, CMS and SEO implementation."}, {"title": "QA & launch", "description": "Cross-device testing, performance, accessibility and go-live."}, {"title": "Optimise", "description": "Analytics review, iteration and continuous improvement."}], "ctaCopy": "Share your goals and current site. You will get a clear, honest recommendation.", "eyebrow": "Technology", "related": ["mobile-development", "chatbot-solutions", "meta-ads"], "audience": "Founders, service businesses, D2C brands, B2B companies and startups that need a credible, high-performing website instead of a template.", "basePath": "/services", "benefits": [{"title": "More qualified inquiries", "description": "Clear messaging and visible CTAs on every section."}, {"title": "Stronger first impression", "description": "Premium design that matches the quality of your work."}, {"title": "Better search visibility", "description": "Technical SEO and structured data from day one."}, {"title": "Lower maintenance cost", "description": "Clean architecture that is cheap to extend."}], "category": "technology", "features": ["Mobile-first responsive layouts", "Accessible, semantic HTML", "Core Web Vitals optimisation", "SEO and AEO ready content structure", "Schema.org structured data", "Analytics and event tracking", "Secure forms with validation", "Reusable component library"], "heroCopy": "We design and engineer websites that load fast, rank well, explain your offer clearly and turn visitors into qualified inquiries.", "imageAlt": "Website Development", "problems": ["The site looks dated next to competitors, so buyers hesitate", "Slow load times and poor Core Web Vitals lose mobile visitors", "The offer is buried, visitors cannot tell what you do in five seconds", "No SEO structure, so the site never appears in relevant searches", "Content cannot be updated without a developer"], "seoTitle": "Website Development Services | React, Next.js & .NET | Work With Vrajesh", "useCases": ["A consulting firm replacing a slow, outdated site", "A manufacturer building a multi-product catalogue website", "A startup launching a SaaS marketing site plus app", "A retailer moving to a custom e-commerce experience", "A services brand needing landing pages for paid campaigns"], "solutions": ["Message-first structure that answers who you help and how", "Design system built on your brand, not a purchased theme", "Component-based, CMS-ready architecture your team can edit", "Technical SEO, structured data and AEO content built in", "Performance budgets, optimised images and lazy loading"], "primaryCta": {"href": "/contact", "label": "Get a Website Inquiry"}, "techGroups": [{"group": "Frontend", "items": ["React", "Next.js", "Angular", "HTML", "CSS", "JavaScript", "TypeScript"]}, {"group": "Backend", "items": ["Node.js", ".NET", "ASP.NET Core", "C#", "Python", "REST APIs"]}, {"group": "Database", "items": ["SQL Server", "PostgreSQL", "MySQL", "MongoDB", "Supabase"]}], "cardSummary": "Corporate sites, web apps and conversion-focused platforms engineered for speed, search and inquiries.", "ctaHeadline": "Ready for a website that actually sells?", "deliverables": [{"title": "Corporate & business websites", "description": "Credibility-first sites with clear service architecture and strong inquiry paths."}, {"title": "Landing pages", "description": "Focused campaign pages built around a single conversion goal."}, {"title": "E-commerce websites", "description": "Catalogue, cart, checkout and payment integrations with clean product UX."}, {"title": "CMS websites", "description": "Editable content models so marketing can publish without developer help."}, {"title": "Web applications", "description": "Dashboards, portals and internal tools with authentication and role-based access."}, {"title": "SaaS platforms", "description": "Multi-tenant products with subscriptions, onboarding and usage analytics."}, {"title": "API integrations", "description": "CRM, payments, ERP, analytics and third-party services connected reliably."}, {"title": "Conversion-focused websites", "description": "Existing sites rebuilt around clarity, speed and inquiry generation."}], "directAnswer": "Website development is the design, engineering and launch of a business website or web application, covering strategy, UX, UI, frontend and backend code, integrations, SEO foundations, performance and ongoing improvement.", "problemIntro": "Most business websites fail commercially long before they fail technically.", "categoryLabel": "Technology", "homepageOrder": 1, "solutionIntro": "We rebuild the website as a commercial asset: clear messaging, premium design and clean engineering.", "showOnHomepage": true, "metaDescription": "Custom website development services, corporate websites, e-commerce, web applications and SaaS platforms built with React, Next.js, Node.js, .NET and PostgreSQL."}', '2026-08-17 14:06:34', '2026-08-18 08:27:35', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('500725c4-917a-4a73-b1b5-d492b385ade7', 'services', 'mobile-development', 1, 'published', '{"h1": "Mobile Apps Your Customers Actually Keep on Their Phone", "faqs": [{"answer": "Flutter suits highly custom, animation-rich interfaces with consistent rendering across platforms. React Native suits teams already invested in the JavaScript and React ecosystem or sharing logic with a web app. We recommend based on your team, timeline and feature set.", "question": "Should I choose Flutter or React Native?"}, {"answer": "Yes. Cross-platform frameworks share a single codebase across both platforms while still allowing native modules where a platform-specific capability is required.", "question": "Can one app work on both Android and iOS?"}, {"answer": "Yes. We integrate payment gateways and in-app purchase or subscription flows, including receipts, refunds handling and store compliance requirements.", "question": "Can you add payments and subscriptions?"}, {"answer": "Yes. We prepare store assets, privacy declarations, build signing and submissions, and support the review process until the app is live.", "question": "Do you handle App Store and Play Store publishing?"}, {"answer": "Yes. We connect apps to existing REST APIs, CRMs, ERPs and databases, or build a new backend using Node.js, .NET, Firebase or Supabase.", "question": "Can the app connect to our existing systems?"}], "name": "Mobile Development", "slug": "mobile-development", "image": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787041686667-0cbsc-mobile-development.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MDQxNjg2NjY3LTBjYnNjLW1vYmlsZS1kZXZlbG9wbWVudC53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzA0MTY4NiwiZXhwIjoxOTQ0NzIxNjg2fQ.kPwbd_G6_JePIFaYGJ1M8R7a5JlOw42vEnHDDHD4-pY", "steps": [{"title": "Idea validation", "description": "Clarify the core job the app must do."}, {"title": "UX flows", "description": "Screens, states and edge cases mapped before code."}, {"title": "Build", "description": "App, APIs, integrations and notifications."}, {"title": "Test", "description": "Device testing, performance and security checks."}, {"title": "Release", "description": "Store submission, review support and launch."}, {"title": "Iterate", "description": "Analytics-driven improvements after launch."}], "ctaCopy": "Tell us the problem it solves and we will map a realistic delivery plan.", "eyebrow": "Technology", "related": ["website-development", "whatsapp-automation", "chatbot-solutions"], "audience": "Businesses digitising a service, brands launching customer apps, and teams that need internal apps for field or operations staff.", "basePath": "/services", "benefits": [{"title": "Faster time to market", "description": "One codebase covers Android and iOS."}, {"title": "Lower long-term cost", "description": "Shared logic means cheaper features and fixes."}, {"title": "Higher retention", "description": "Notifications and smooth UX bring users back."}, {"title": "Reliable operations", "description": "Backend and app designed together, not patched."}], "category": "technology", "features": ["Offline-friendly data handling", "Push notifications", "In-app payments", "Role-based access", "Deep linking", "Crash and usage analytics", "Over-the-air updates where supported", "App store and Play Store release support"], "heroCopy": "From idea to store launch, cross-platform apps that feel native, run fast and connect cleanly to your business systems.", "imageAlt": "Mobile Development", "problems": ["Two separate codebases double the cost and slow every release", "The app ships without analytics, so nobody knows what users do", "Push notifications and payments are bolted on late and break", "No offline handling, so field teams cannot rely on it", "Store rejections caused by policy and privacy oversights"], "seoTitle": "Mobile App Development Services | Flutter & React Native | Work With Vrajesh", "useCases": ["A clinic offering appointment booking and reminders", "A retail brand launching a mobile store with payments", "A logistics team capturing field data offline", "A gym running memberships and class bookings", "A B2B company giving clients an order-tracking app"], "solutions": ["Cross-platform delivery with Flutter or React Native where it fits", "Native Android and iOS work where platform depth is required", "Secure authentication, roles and data rules from the start", "Payments, notifications and analytics designed into the architecture", "Store submission, review readiness and release management"], "primaryCta": {"href": "/contact", "label": "Discuss My App Idea"}, "techGroups": [{"group": "App", "items": ["Flutter", "React Native", "Android", "iOS"]}, {"group": "Backend & data", "items": ["Firebase", "Supabase", "REST APIs", "Node.js", ".NET"]}, {"group": "Capabilities", "items": ["Payment Integrations", "Push Notifications", "Authentication", "Analytics"]}], "cardSummary": "Cross-platform and native mobile apps with payments, notifications and reliable backends.", "ctaHeadline": "Have an app idea worth building?", "deliverables": [{"title": "Business apps", "description": "Operational apps that digitise a real internal workflow."}, {"title": "Customer apps", "description": "Loyalty, service and account apps that increase retention."}, {"title": "E-commerce apps", "description": "Catalogue, cart, checkout and order tracking on mobile."}, {"title": "Booking apps", "description": "Appointments, availability, reminders and rescheduling."}, {"title": "Internal business apps", "description": "Field data capture, approvals and reporting tools."}, {"title": "Custom applications", "description": "Product ideas engineered from prototype to release."}], "directAnswer": "Mobile app development is the design, engineering, testing and store release of Android and iOS applications, including backend APIs, authentication, payments, notifications and analytics.", "problemIntro": "Most app projects stall for predictable reasons.", "categoryLabel": "Technology", "homepageOrder": 2, "solutionIntro": "We build one maintainable codebase with the production details planned upfront.", "showOnHomepage": true, "metaDescription": "Mobile app development with Flutter and React Native for Android and iOS, business apps, e-commerce apps, booking apps, payments, push notifications and Firebase or Supabase backends."}', '2026-08-17 14:06:34', '2026-08-18 08:28:36', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4cda1ee1-1512-4909-a8b5-efb24c036e88', 'case_studies', 'dealership-service-booking-voice-bot-australia', 35, 'published', '{"slug": "dealership-service-booking-voice-bot-australia", "team": "1 AI engineer, 1 conversation designer, 1 telephony engineer", "title": "Service booking calls handled for an automotive dealership group", "country": "Australia", "metrics": [], "features": ["Workshop-capacity aware scheduling", "Registration lookup and service history awareness", "Multi-site call routing", "SMS confirmations and reminders", "Missed-call and booking reporting per site"], "industry": "Automotive", "outcomes": ["Customers book a service slot on the first call, not the third attempt", "Advisers stay with customers instead of chasing voicemails", "The group can finally see call volume and booking rates per site"], "solution": [{"title": "Capacity-aware booking", "description": "The assistant books only into slots the workshop system confirms as available for that job type."}, {"title": "Vehicle-aware conversation", "description": "Registration lookup pulls service history so the right job type and duration are proposed."}, {"title": "Group-wide consistency", "description": "One conversational standard across all dealerships, with site-specific hours and capacity."}, {"title": "Confirmation and reminders", "description": "SMS confirmation, reminder and reschedule links generated from the call."}], "challenge": "Service advisers were on the workshop floor with customers while the phone rang unanswered. Callers left voicemails that were returned hours later, by which time the workshop slot had gone. Across several dealerships, each site handled bookings differently and no one had a group view of missed calls.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787124546895-01h9a-c9c5ac2b-74b7-4f26-9185-f2f8a9b465ce.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTI0NTQ2ODk1LTAxaDlhLWM5YzVhYzJiLTc0YjctNGYyNi05MTg1LWYyZjhhOWI0NjVjZS53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyNDU0NiwiZXhwIjoxOTQ0ODA0NTQ2fQ.eiX2szMy8euWFMx1WbOBojalHO5lfVyEFqNje5EpWP0", "valueProp": "A service desk that answers every call at 8am.", "afterState": ["Every call answered", "Booking completed on the call", "One standard across sites", "Group-level call reporting"], "clientName": "Amy Roberston", "objectives": ["Answer and book service calls without adviser involvement", "Schedule against actual workshop capacity", "Standardise booking across every site"], "serviceKey": "voice-bot-solutions", "beforeState": ["Unanswered service calls", "Late voicemail callbacks", "Inconsistent site processes", "No group reporting"], "countryCode": "au", "placeholder": true, "publishedDate": "2025-10-16", "challengePoints": ["Service advisers unable to answer phones while serving customers", "Voicemail callbacks arriving after slots were filled", "Inconsistent booking processes across dealerships"], "projectDuration": "8 weeks", "clientDescriptor": "Automotive dealership group", "shortDescription": "Service department calls answered, scheduled against real workshop capacity and confirmed automatically across multiple dealerships."}', '2026-08-17 14:05:37', '2026-08-19 07:29:12', NULL);
