INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('0e250560-e70f-40d9-9802-bd5bb1c1664d', 'faqs_home', 'Can you handle both the website and the marketing?', 2, 'published', '{"answer": "Yes. That is the main reason clients choose us. The website, campaigns and automation are planned together, so traffic, messaging and follow-up all support the same goal.", "question": "Can you handle both the website and the marketing?"}', '2026-08-17 15:04:19', '2026-08-17 15:04:19', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('320784d7-2ee5-48f1-a386-001c1d158952', 'faqs_home', 'How do projects start?', 3, 'published', '{"answer": "With a discovery call. We review your goals, audience and current setup, then send a clear scope with deliverables, timeline and the outcome each phase targets.", "question": "How do projects start?"}', '2026-08-17 15:04:19', '2026-08-17 15:04:19', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('3254668b-d462-41b0-84e0-e3408dff0833', 'faqs_home', 'How much does a project cost?', 4, 'published', '{"answer": "Pricing depends on scope. A focused website or a single automation is far smaller than a full technology plus marketing engagement. Share your requirement and budget range and we will recommend the highest-impact starting point.", "question": "How much does a project cost?"}', '2026-08-17 15:04:19', '2026-08-17 15:04:19', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('a6572769-8e8c-435e-acd1-8d034fcc6232', 'faqs_home', 'Will the website be editable by our team?', 5, 'published', '{"answer": "Yes. Everything is built component-based and CMS-ready, so services, testimonials, case studies, FAQs, statistics, homepage sections, CTAs, contact details and SEO metadata can be updated without a developer.", "question": "Will the website be editable by our team?"}', '2026-08-17 15:04:19', '2026-08-17 15:04:19', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('5d4c7517-4328-477c-b75a-72c0c409fd98', 'faqs_ai', 'Which channels can be automated?', 1, 'published', '{"answer": "Website chat, WhatsApp, Facebook Messenger and comments, Instagram DMs and inbound phone calls. Each channel can share the same knowledge base and escalation rules.", "question": "Which channels can be automated?"}', '2026-08-17 15:04:19', '2026-08-17 15:04:19', NULL);
