INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('8dcd8458-5b22-493f-8ded-7e3953aec4cb', 'testimonials', 'daniel-whitfield', 2, 'published', '{"id": "daniel-whitfield", "quote": "Timezones were my biggest worry working with a team in India. Honestly it was a non-issue, updates every few days, clear notes, and nothing needed chasing. The build was live ahead of what we planned.", "company": "Northline Fitouts", "featured": true, "location": "Melbourne, Australia", "clientName": "Daniel Whitfield", "designation": "Founder", "serviceUsed": "Website Development"}', '2026-08-17 14:05:32', '2026-08-17 19:36:16', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('74a8902a-3671-417e-b388-ab96fe35920a', 'case_studies', 'recruitment-founder-pipeline-australia', 19, 'published', '{"slug": "recruitment-founder-pipeline-australia", "team": "1 strategist, 1 ghostwriter", "title": "Turning a recruitment founder''s profile into a two-sided pipeline", "country": "Australia", "metrics": [], "features": ["Dual-audience editorial map", "Recurring market intelligence series", "Candidate guidance content library", "Profile conversion paths for both audiences", "Monthly inbound source review"], "industry": "Recruitment & staffing", "outcomes": ["Hiring managers follow for the market data, not the vacancies", "Candidates register even when no relevant role is open", "The agency has a recognisable voice beyond job listings"], "solution": [{"title": "Dual-audience content map", "description": "Alternating employer and candidate themes with a shared, consistent tone."}, {"title": "Market intelligence series", "description": "Salary trends, hiring timelines and skill demand published from real placement observations."}, {"title": "Candidate honesty content", "description": "Interview and negotiation guidance that helps whether or not the reader applies."}, {"title": "Inbound handling", "description": "Clear routes for hiring enquiries and candidate registrations from the profile."}], "challenge": "The founder posted job ads, which candidates ignored and hiring managers never saw. Both audiences needed different things, market intelligence for employers, honest career guidance for candidates, and the account served neither. Competing agencies were building genuine audiences while this one broadcast vacancies.", "valueProp": "One voice that both sides of the market want to follow.", "afterState": ["Two-audience content system", "Useful market intelligence", "Distinct market voice", "Vacancy-independent pipeline"], "clientName": "[Client Name]", "objectives": ["Attract hiring managers with market intelligence", "Attract candidates with genuinely useful career content", "Build a reputation independent of live vacancies"], "serviceKey": "linkedin-personal-branding", "beforeState": ["Job-ad broadcasting", "Low engagement", "Undifferentiated brand", "Vacancy-dependent visibility"], "countryCode": "au", "placeholder": true, "publishedDate": "2025-10-20", "challengePoints": ["Job-ad posting that neither audience engaged with", "Two distinct audiences with conflicting content needs", "No differentiation from competing agencies"], "projectDuration": "4 months (ongoing retainer)", "clientDescriptor": "Specialist recruitment agency founder", "shortDescription": "One profile built to attract hiring managers and candidates at once, without either audience feeling advertised to."}', '2026-08-17 14:05:37', '2026-08-17 19:36:16', NULL);
