INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4c6ff1c4-22a2-4f96-b64d-1ec1c722a65b', 'services', 'linkedin-personal-branding', 3, 'published', '{"h1": "Build LinkedIn Authority That Brings Buyers to You", "faqs": [{"answer": "It is the process of positioning a person, usually a founder or expert, so their profile and content consistently communicate who they help, how they help and why they are credible, which turns LinkedIn into an inbound channel.", "question": "What is LinkedIn personal branding?"}, {"answer": "People trust people faster than brands. A founder publishing consistently shortens sales cycles, creates warm inbound conversations, supports the sales team''s outreach and improves hiring and partnership opportunities.", "question": "How can LinkedIn personal branding help a business?"}, {"answer": "Client problems and how they were solved, lessons from delivery, industry opinions, behind-the-scenes decisions, frameworks you use, and occasional clear offers. Aim for roughly 80% value and 20% direct offer.", "question": "What should founders post on LinkedIn?"}, {"answer": "Yes. Consistent, buyer-focused posting combined with targeted engagement generates profile views, DMs and inbound inquiries. Results typically build over 60\\u201390 days of steady publishing.", "question": "Can LinkedIn personal branding generate leads?"}, {"answer": "Yes. We start with voice interviews and existing material, then draft in your language. You review every post before it goes live.", "question": "Will the posts sound like me?"}], "name": "LinkedIn Personal Branding", "slug": "linkedin-personal-branding", "image": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787043045987-rabza-linkedin-personal-branding.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MDQzMDQ1OTg3LXJhYnphLWxpbmtlZGluLXBlcnNvbmFsLWJyYW5kaW5nLndlYnAiLCJzY29wZSI6ImRvd25sb2FkIiwiaWF0IjoxNzg3MDQzMDQ2LCJleHAiOjE5NDQ3MjMwNDZ9.-UVgzl9S9XP6FVNtp9mvSUePMXpwRgW8OYjTX4ucTfo", "steps": [{"title": "Positioning", "description": "Define audience, promise and point of view."}, {"title": "Profile rebuild", "description": "Every section rewritten for conversion."}, {"title": "Content system", "description": "Pillars, formats and calendar."}, {"title": "Publishing", "description": "Weekly drafts, edits and scheduling."}, {"title": "Engagement", "description": "Targeted commenting and conversation handling."}, {"title": "Review", "description": "Monthly performance and message refinement."}], "ctaCopy": "Share your profile and we will show you what to fix first.", "eyebrow": "Marketing & Growth", "related": ["social-media-marketing", "email-marketing", "website-development"], "audience": "Founders, consultants, agency owners, sales leaders and B2B professionals who sell through credibility.", "basePath": "/services", "benefits": [{"title": "Inbound instead of cold outreach", "description": "Buyers arrive pre-sold on your thinking."}, {"title": "Shorter sales cycles", "description": "Content answers objections before the call."}, {"title": "Talent and partnerships", "description": "Authority attracts more than clients."}, {"title": "Compounding asset", "description": "Your profile keeps working after every post."}], "category": "marketing", "features": ["Buyer-language headline and about section", "Post formats: story, insight, teardown, proof, offer", "Comment strategy on target accounts", "Content repurposing to other channels", "Monthly analytics: impressions, profile views, inbound"], "heroCopy": "Positioning, profile and publishing built around the way your buyers actually make decisions.", "imageAlt": "linkedin-personal-branding", "problems": ["The profile reads like a resume, not an offer", "Posts are random, so the audience never learns what you stand for", "Engagement comes from peers, not buyers", "No system to turn comments into conversations", "Fear of publishing without a repeatable format"], "seoTitle": "LinkedIn Personal Branding Services for Founders | Work With Vrajesh", "useCases": ["An agency founder building inbound demand", "A consultant launching a new offer", "A SaaS founder sharing build-in-public insights", "A sales leader supporting the team''s pipeline", "A professional preparing for a career or category shift"], "solutions": ["Positioning statement and profile rewrite that sells the outcome", "Content pillars mapped to buyer objections and decisions", "Ghostwritten posts in your voice with a weekly cadence", "Engagement routine that reaches the accounts you want", "Inbound conversation flow from comment to call"], "primaryCta": {"href": "/contact", "label": "Build My LinkedIn Authority"}, "techGroups": [{"group": "Platform", "items": ["LinkedIn", "LinkedIn Creator tools", "Sales Navigator (optional)"]}, {"group": "Craft", "items": ["Positioning", "Ghostwriting", "Narrative design", "Content repurposing"]}, {"group": "Measurement", "items": ["Impressions", "Profile views", "Inbound conversations"]}], "cardSummary": "Founder-led authority: optimised profile, content strategy and inbound conversations.", "ctaHeadline": "Make LinkedIn your best sales channel", "deliverables": [{"title": "Profile optimisation", "description": "Headline, about, banner, featured and experience rewritten."}, {"title": "Personal brand positioning", "description": "The specific space you own in your buyer''s mind."}, {"title": "Content strategy", "description": "Pillars, formats and cadence documented."}, {"title": "Thought leadership writing", "description": "Weekly posts drafted in your voice."}, {"title": "Founder branding", "description": "Narrative that connects your story to the business."}, {"title": "LinkedIn lead generation", "description": "Engagement and outreach that starts real conversations."}], "directAnswer": "LinkedIn personal branding is the deliberate positioning of a founder or professional on LinkedIn, profile optimisation, a documented content strategy, consistent publishing and structured engagement, so the right buyers discover, trust and contact them.", "problemIntro": "Most founders post occasionally and wonder why nothing happens.", "categoryLabel": "Marketing & Growth", "solutionIntro": "We turn expertise into a publishing system with a clear commercial angle.", "metaDescription": "LinkedIn personal branding services, profile optimisation, founder content strategy, thought leadership writing and LinkedIn lead generation that creates inbound conversations."}', '2026-08-17 14:06:34', '2026-08-18 08:51:02', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('2d079b3f-9fef-4ec5-8d8b-51fa605c0446', 'services', 'facebook-automation', 8, 'published', '{"h1": "Facebook Automation That Turns Comments Into Customers", "faqs": [{"answer": "It is the use of AI and rule-based flows on Facebook Messenger, page comments and Instagram DMs to reply instantly, answer common questions, collect contact details and route qualified conversations to your team.", "question": "What is Facebook automation?"}, {"answer": "Yes. Keyword triggers can post a public reply and simultaneously send a private message with details, pricing or a booking link, which is especially effective on ad posts.", "question": "Can comments be answered automatically?"}, {"answer": "It usually improves it. Faster first response and structured qualification increase the share of ad clicks that become contactable leads, which lowers effective cost per qualified lead.", "question": "Does automation affect ad performance?"}, {"answer": "No, when built on official Meta platform tools and within messaging policy windows and opt-in rules. We design flows that respect those limits.", "question": "Is it against Meta''s policies?"}, {"answer": "Yes. Many businesses run Facebook and Instagram automation alongside WhatsApp automation so every Meta channel shares the same qualification logic and CRM destination.", "question": "Can it work together with WhatsApp automation?"}], "name": "Facebook & Instagram Automation", "slug": "facebook-automation", "image": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787044301724-an74v-social-media-automations.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MDQ0MzAxNzI0LWFuNzR2LXNvY2lhbC1tZWRpYS1hdXRvbWF0aW9ucy53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzA0NDMwMSwiZXhwIjoxOTQ0NzI0MzAxfQ.KGHZN31VItYEPXihIQE0ei8fghukRJ8VmdczJ4iMmlE", "steps": [{"title": "Audit", "description": "Current inbox volume, questions and gaps."}, {"title": "Flow design", "description": "Triggers, replies, qualification and handover."}, {"title": "Build", "description": "Automation setup across channels."}, {"title": "Connect", "description": "CRM, notifications and reporting."}, {"title": "Test", "description": "Live testing across ads and organic posts."}, {"title": "Refine", "description": "Improve based on real conversations."}], "ctaCopy": "Share your page volume and campaigns, we will design the automation.", "eyebrow": "AI & Automation", "related": ["whatsapp-automation", "meta-ads", "chatbot-solutions"], "audience": "Brands running Meta Ads, pages receiving high comment volume, and businesses selling through Messenger or Instagram DMs.", "basePath": "/ai-solutions", "benefits": [{"title": "Better ad ROI", "description": "Instant replies convert more ad clicks."}, {"title": "No lost DMs", "description": "Every message gets a structured response."}, {"title": "Cleaner data", "description": "Social leads land in your CRM automatically."}, {"title": "Time saved", "description": "Your team handles only real conversations."}], "category": "ai", "features": ["24/7 auto-response", "Keyword and intent triggers", "Human handover", "Quick reply buttons and menus", "Conversation tagging and segmentation", "Performance reporting"], "heroCopy": "Every comment, DM and ad conversation answered instantly, and captured as a lead instead of disappearing in the inbox.", "imageAlt": "facebook-automation", "problems": ["Ad comments asking for price go unanswered", "DMs pile up across Messenger and Instagram", "Interested people never move from comment to contact", "No record of social conversations in the CRM", "Response times destroy otherwise good ad performance"], "seoTitle": "Facebook Automation | Messenger, Comment & DM Automation | Work With Vrajesh", "useCases": ["Price enquiries in ad comments", "Lead capture from Click-to-Messenger campaigns", "Instagram story reply automation", "Customer support triage", "Event and webinar registrations", "Product recommendation conversations"], "solutions": ["Keyword-triggered comment replies with DM follow-up", "Messenger flows that answer and qualify", "Instagram DM automation for story replies and mentions", "Lead capture with email and phone collection", "Ad-specific conversation flows per campaign"], "primaryCta": {"href": "/contact", "label": "Automate My Social Inbox"}, "techGroups": [{"group": "Channels", "items": ["Messenger", "Facebook comments", "Instagram DM", "Click-to-Messenger ads"]}, {"group": "AI", "items": ["Intent detection", "AI replies", "Guardrails"]}, {"group": "Integrations", "items": ["CRM", "Email platforms", "Google Sheets", "Webhooks"]}], "cardSummary": "Messenger, comment and Instagram DM automation that converts social attention into leads.", "ctaHeadline": "Reply to every comment and DM instantly", "deliverables": [{"title": "Messenger automation", "description": "Instant replies, menus and qualification flows."}, {"title": "Comment automation", "description": "Keyword triggers that reply publicly and privately."}, {"title": "Instagram DM flows", "description": "Story reply, mention and keyword automation."}, {"title": "Lead capture", "description": "Contact details collected inside the conversation."}, {"title": "Ad conversation flows", "description": "Click-to-Messenger campaigns handled end to end."}, {"title": "CRM sync", "description": "Leads and transcripts pushed to your systems."}], "directAnswer": "Facebook automation connects AI and rule-based flows to Messenger, page comments and Instagram DMs so enquiries are answered instantly, leads are captured with contact details, and conversations sync to your CRM.", "problemIntro": "Social attention is worthless if nobody replies in time.", "categoryLabel": "AI & Automation", "solutionIntro": "We automate the first response and the capture, then hand people to your team.", "metaDescription": "Facebook automation for Messenger, comments and Instagram DMs, auto-replies, comment-to-DM flows, lead capture, ad conversation automation and CRM integration."}', '2026-08-17 14:06:34', '2026-08-18 09:11:43', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('9d7632bb-60cf-4a6d-83b7-0f044a186ab8', 'services', 'social-media-marketing', 2, 'published', '{"h1": "Social Media That Builds a Brand, Not Just a Feed", "faqs": [{"answer": "Strategy, content pillars, a monthly calendar, creative production (reels, carousels, statics), publishing, community management and monthly performance reporting.", "question": "What does a social media marketing service include?"}, {"answer": "Consistency matters more than volume. Most businesses see traction with 12\\u201320 quality assets per month, weighted toward short-form video, published on a predictable schedule.", "question": "How many posts should a business publish per month?"}, {"answer": "Reach and engagement usually shift within 4\\u20136 weeks. Inquiry volume typically becomes stable around month three, once content pillars and the best-performing formats are identified.", "question": "How long before social media produces results?"}, {"answer": "We create it. Scripting, design, editing and captions are handled in-house, with your input on offers, product detail and approvals.", "question": "Do you create the content or only schedule it?"}, {"answer": "Yes, when content answers buyer questions and each post has a clear next step. Pairing organic content with DM automation and Meta Ads shortens the path from attention to inquiry.", "question": "Can social media generate actual leads?"}], "name": "Social Media Marketing", "slug": "social-media-marketing", "image": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787042351691-kiszv-social-media-marketing.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MDQyMzUxNjkxLWtpc3p2LXNvY2lhbC1tZWRpYS1tYXJrZXRpbmcud2VicCIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODcwNDIzNTEsImV4cCI6MTk0NDcyMjM1MX0.9ZaFZfSyNs-6XgpIpZiHthx08-sUbRDtoAWam2H6MIA", "steps": [{"title": "Audit", "description": "Current profiles, content and competitor benchmarks."}, {"title": "Strategy", "description": "Pillars, tone, formats and posting cadence."}, {"title": "Production", "description": "Batch creation of monthly creative."}, {"title": "Publish", "description": "Scheduling, captions and community engagement."}, {"title": "Report", "description": "Monthly review and next-month plan."}], "ctaCopy": "Send your handles and goals, we will point out the quickest wins.", "eyebrow": "Marketing & Growth", "related": ["meta-ads", "linkedin-personal-branding", "facebook-automation"], "audience": "Service businesses, D2C brands, local businesses and founders who need consistent, on-brand content that supports sales.", "basePath": "/services", "benefits": [{"title": "Consistent brand presence", "description": "A recognisable feed that builds recall."}, {"title": "Warmer leads", "description": "Buyers arrive already understanding your offer."}, {"title": "Content that compounds", "description": "Pillars and repurposing reduce cost per asset."}, {"title": "Clear reporting", "description": "Metrics tied to inquiries, not vanity numbers."}], "category": "marketing", "features": ["Brand-consistent templates", "Hook-first short-form scripting", "Reels and short video editing", "Content repurposing across channels", "Competitor and trend monitoring", "Monthly performance review"], "heroCopy": "A content system with a point of view, planned, produced and measured so social becomes a dependable source of attention and inquiries.", "imageAlt": "social-media-marketing", "problems": ["Content is inconsistent and off-brand", "Reels get views but never lead to inquiries", "No clear content pillars, so every post starts from zero", "Comments and DMs go unanswered", "Reporting stops at likes and follower counts"], "seoTitle": "Social Media Marketing Services | Instagram & Facebook Growth | Work With Vrajesh", "useCases": ["A restaurant building local awareness with reels", "A clinic educating patients through short explainers", "A D2C brand launching a product line", "A B2B firm humanising the team behind the service", "A coach turning content into consultation bookings"], "solutions": ["Positioning and content pillars based on buyer questions", "Monthly content calendar with formats mapped to intent", "Reels, carousels and static creative in a consistent visual system", "Community management and DM response workflow", "Monthly reporting on reach, engagement, saves and inquiries"], "primaryCta": {"href": "/contact", "label": "Grow My Social Presence"}, "techGroups": [{"group": "Platforms", "items": ["Instagram", "Facebook", "YouTube Shorts", "LinkedIn"]}, {"group": "Production", "items": ["Short-form video", "Carousel design", "Copywriting", "Brand templates"]}, {"group": "Measurement", "items": ["Meta Business Suite", "UTM tracking", "Analytics dashboards"]}], "cardSummary": "Strategy, content and community management that turn attention into pipeline.", "ctaHeadline": "Turn your feed into a pipeline", "deliverables": [{"title": "Social strategy", "description": "Audience, positioning, pillars and platform priorities."}, {"title": "Content calendar", "description": "Planned monthly schedule with themes and hooks."}, {"title": "Creative production", "description": "Reels, carousels, stories and static posts."}, {"title": "Instagram & Facebook management", "description": "Publishing, captions, hashtags and scheduling."}, {"title": "Community management", "description": "Comment and DM responses that move people forward."}, {"title": "Analytics & reporting", "description": "What worked, what to repeat, what to stop."}], "directAnswer": "Social media marketing is the ongoing planning, creation, publishing, community management and measurement of brand content on platforms such as Instagram and Facebook to build awareness, trust and demand.", "problemIntro": "Posting more is not a strategy.", "categoryLabel": "Marketing & Growth", "solutionIntro": "We build a repeatable content engine tied to commercial outcomes.", "metaDescription": "Social media marketing services covering strategy, content creation, Instagram and Facebook management, reels, community engagement, analytics and measurable growth."}', '2026-08-17 14:06:34', '2026-08-18 08:40:03', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('13d40027-7e69-415d-b72e-33236c15f5e5', 'services', 'chatbot-solutions', 6, 'published', '{"h1": "AI Chatbots That Qualify Leads While You Sleep", "faqs": [{"answer": "It can answer product and service questions, qualify leads, capture contact details, book appointments, share documents, provide order or status updates, and escalate anything complex to a human with full context.", "question": "What can an AI chatbot automate?"}, {"answer": "Yes. The bot asks the same qualification questions your sales team would, need, timeline, budget range and decision role, and scores or routes the lead accordingly, so your team only spends time on real opportunities.", "question": "Can AI qualify leads reliably?"}, {"answer": "We restrict the assistant to your approved knowledge base with explicit guardrails. When it cannot answer confidently, it says so and offers human handover instead of guessing.", "question": "Will the chatbot invent answers?"}, {"answer": "Yes. Conversations, contact details and qualification data can be pushed to your CRM, email or internal tools automatically through APIs or webhooks.", "question": "Can it connect to our CRM?"}, {"answer": "A focused website chatbot with qualification and booking typically takes 1\\u20133 weeks depending on how much source content and how many integrations are involved.", "question": "How long does chatbot deployment take?"}], "name": "Chatbot Solutions", "slug": "chatbot-solutions", "image": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787043413155-vbdif-chatbot-solutions.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MDQzNDEzMTU1LXZiZGlmLWNoYXRib3Qtc29sdXRpb25zLndlYnAiLCJzY29wZSI6ImRvd25sb2FkIiwiaWF0IjoxNzg3MDQzNDEzLCJleHAiOjE5NDQ3MjM0MTN9.uHNddEKJ53oCO7hD26AKQ6PxOZZBUpzxcfrUF3eclQQ", "steps": [{"title": "Use-case mapping", "description": "Decide what the bot should and should not do."}, {"title": "Knowledge build", "description": "Collect and structure source content."}, {"title": "Conversation design", "description": "Flows, tone, qualification and handover."}, {"title": "Integration", "description": "CRM, calendar and notification wiring."}, {"title": "Testing", "description": "Accuracy, edge cases and escalation checks."}, {"title": "Improve", "description": "Monthly transcript review and retraining."}], "ctaCopy": "Tell us the questions your team repeats most, that is where we start.", "eyebrow": "AI & Automation", "related": ["whatsapp-automation", "voice-bot-solutions", "website-development"], "audience": "Businesses receiving repetitive questions, teams losing after-hours leads, and companies that need faster first response.", "basePath": "/ai-solutions", "benefits": [{"title": "Instant first response", "description": "Every visitor is answered in seconds."}, {"title": "More qualified conversations", "description": "Sales talks only to real prospects."}, {"title": "Lower support load", "description": "Repetitive questions handled automatically."}, {"title": "Round-the-clock coverage", "description": "Nights, weekends and holidays included."}], "category": "ai", "features": ["Multi-language responses", "Guardrails against off-topic answers", "Conversation history and transcripts", "Lead capture with validation", "CRM, email and Slack notifications", "Continuous improvement from real transcripts"], "heroCopy": "A trained assistant on your website and channels that answers accurately, captures details and routes real opportunities to your team.", "imageAlt": "chatbot-solutions", "problems": ["Inquiries arrive at night and are answered the next morning", "The same ten questions consume hours of team time", "Visitors leave because pricing or process is unclear", "Lead details are collected inconsistently", "Support tickets pile up for issues already documented"], "seoTitle": "AI Chatbot Solutions for Business Websites | Work With Vrajesh", "useCases": ["Lead qualification before a sales call", "Customer support for common questions", "Appointment booking", "Instant FAQ answers", "Lead follow-ups and reminders", "Customer onboarding guidance"], "solutions": ["Knowledge base built from your services, policies and FAQs", "Qualification flow that captures budget, timeline and intent", "Appointment booking directly in conversation", "Human handover with full conversation context", "CRM and email notification integration"], "primaryCta": {"href": "/contact", "label": "Automate My Business"}, "techGroups": [{"group": "AI", "items": ["LLM assistants", "Retrieval-augmented answers", "Prompt guardrails"]}, {"group": "Channels", "items": ["Website widget", "WhatsApp", "Messenger", "Instagram DM"]}, {"group": "Integrations", "items": ["CRM", "Calendars", "Email", "REST APIs", "Supabase"]}], "cardSummary": "AI assistants on your website that answer questions, qualify leads and book calls instantly.", "ctaHeadline": "Answer every visitor in seconds", "deliverables": [{"title": "Website chatbot", "description": "Branded assistant embedded on every page."}, {"title": "Knowledge training", "description": "Trained on your services, FAQs and documents."}, {"title": "Lead qualification", "description": "Structured questions that score intent."}, {"title": "Appointment booking", "description": "Slots captured and confirmed in chat."}, {"title": "Human handover", "description": "Escalation rules with context transfer."}, {"title": "Analytics", "description": "Top questions, drop-offs and conversion tracking."}], "directAnswer": "An AI chatbot is a conversational assistant trained on your business information that answers visitor questions, qualifies leads, books appointments and escalates complex conversations to a human, working 24/7 across your website and messaging channels.", "problemIntro": "Speed of response decides who wins the deal.", "categoryLabel": "AI & Automation", "solutionIntro": "We deploy a bot trained on your real content with clear boundaries and human handover.", "metaDescription": "AI chatbot solutions that answer customer questions, qualify leads, book appointments and hand over to your team, trained on your business content and integrated with your CRM."}', '2026-08-17 14:06:34', '2026-08-18 08:56:55', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('7ea33c88-0e6a-4cd8-b9fe-57af119e5a94', 'services', 'whatsapp-automation', 7, 'published', '{"h1": "WhatsApp Automation That Replies the Moment People Message", "faqs": [{"answer": "It gives every customer an instant reply, qualifies enquiries automatically, sends reminders and updates without manual effort, and keeps the whole conversation history in one place, which usually improves response time, show-up rate and conversion.", "question": "How can WhatsApp automation help a business?"}, {"answer": "For automation at scale, yes. The free Business app is limited to manual use on one device. The official API supports automation, multiple agents, templates, integrations and reliable delivery.", "question": "Do I need the WhatsApp Business API?"}, {"answer": "Yes, when built correctly. We use the official API, opt-in collection and approved message templates for business-initiated messages, so your number stays in good standing.", "question": "Is WhatsApp automation compliant?"}, {"answer": "Yes. Any conversation can be escalated to a team member in a shared inbox, with full context, and automation can be paused for that contact.", "question": "Can a human take over the conversation?"}, {"answer": "Yes. Leads, tags and conversation summaries can sync to your CRM, and the bot can pull order or booking data from your systems to answer accurately.", "question": "Can WhatsApp connect to our CRM?"}], "name": "WhatsApp Automation", "slug": "whatsapp-automation", "image": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787043832666-3oodk-whatsapp-automations.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MDQzODMyNjY2LTNvb2RrLXdoYXRzYXBwLWF1dG9tYXRpb25zLndlYnAiLCJzY29wZSI6ImRvd25sb2FkIiwiaWF0IjoxNzg3MDQzODMyLCJleHAiOjE5NDQ3MjM4MzJ9.7tiqacbSsmUr1dTaJbrqupvdd-g4jva9mALjQwv_dZM", "steps": [{"title": "Discovery", "description": "Message types, volume and desired outcomes."}, {"title": "API setup", "description": "Business verification and template approval."}, {"title": "Flow design", "description": "Conversation trees, AI answers and handover."}, {"title": "Integration", "description": "CRM, calendar and order systems."}, {"title": "Pilot", "description": "Live testing with real conversations."}, {"title": "Optimise", "description": "Refine flows based on transcripts."}], "ctaCopy": "Tell us how customers message you today and we will design the flow.", "eyebrow": "AI & Automation", "related": ["chatbot-solutions", "facebook-automation", "email-marketing"], "audience": "Businesses whose customers message on WhatsApp: clinics, retail, real estate, education, services and e-commerce.", "basePath": "/ai-solutions", "benefits": [{"title": "Instant response", "description": "No lead waits until morning."}, {"title": "Fewer no-shows", "description": "Automated reminders keep the calendar full."}, {"title": "Higher open rates", "description": "WhatsApp is read far more than email."}, {"title": "Scalable support", "description": "Handle volume without adding headcount."}], "category": "ai", "features": ["24/7 automated responses", "Human takeover at any point", "Multi-agent inbox", "Rich media and quick replies", "Conversation tagging", "CRM and sheet integrations"], "heroCopy": "Meet customers on the channel they already use, with automated conversations that qualify, remind, update and follow up.", "imageAlt": "whatsapp-automation", "problems": ["Messages arrive after hours and are missed", "One shared number, no ownership or tracking", "Manual reminders mean no-shows and missed appointments", "Order and delivery updates are sent one by one", "No record of conversations in the CRM"], "seoTitle": "WhatsApp Automation & WhatsApp Business API Solutions | Work With Vrajesh", "useCases": ["Lead qualification for inbound enquiries", "Appointment booking and reminders", "Order and delivery notifications", "Customer support and FAQs", "Lead follow-ups and re-engagement", "Sales automation with payment links"], "solutions": ["Official WhatsApp Business API setup and verification", "AI replies trained on your services and policies", "Qualification flows that route hot leads to sales", "Automated reminders, confirmations and status updates", "Template messages and opt-in compliant broadcasts"], "primaryCta": {"href": "/contact", "label": "Automate My WhatsApp"}, "techGroups": [{"group": "Channel", "items": ["WhatsApp Business API", "Message templates", "Opt-in management"]}, {"group": "AI", "items": ["Conversational AI", "Intent detection", "Guardrails"]}, {"group": "Integrations", "items": ["CRM", "Calendars", "Payment links", "E-commerce", "REST APIs"]}], "cardSummary": "Automated WhatsApp conversations for enquiries, bookings, order updates and follow-ups.", "ctaHeadline": "Never miss a WhatsApp enquiry again", "deliverables": [{"title": "Business API setup", "description": "Number verification, profile and template approval."}, {"title": "Automated replies", "description": "Instant answers to common questions."}, {"title": "Lead qualification", "description": "Structured conversation that scores intent."}, {"title": "Appointment reminders", "description": "Confirmations, reminders and rescheduling."}, {"title": "Order updates", "description": "Status and delivery notifications."}, {"title": "Broadcasts", "description": "Opt-in campaigns using approved templates."}, {"title": "Team inbox", "description": "Shared inbox with assignment and handover."}], "directAnswer": "WhatsApp automation uses the WhatsApp Business API and AI to handle customer conversations automatically, instant replies, lead qualification, appointment reminders, order updates, follow-ups and broadcasts, with handover to a human when required.", "problemIntro": "WhatsApp is where customers talk, and where leads quietly die.", "categoryLabel": "AI & Automation", "solutionIntro": "We build compliant WhatsApp flows on the official Business API.", "metaDescription": "WhatsApp automation using the WhatsApp Business API, automated replies, lead qualification, appointment reminders, order updates, broadcasts and CRM integration."}', '2026-08-17 14:06:34', '2026-08-18 09:04:02', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('f0b55eea-3947-474e-9a14-9b033f32fc7e', 'services', 'voice-bot-solutions', 9, 'published', '{"h1": "AI Voice Bots That Answer Every Call You Currently Miss", "faqs": [{"answer": "It is a phone agent powered by speech recognition and conversational AI. It understands what a caller says, replies in a natural voice, completes tasks like booking or qualification, and transfers to a human when the request needs one.", "question": "What is an AI voice bot?"}, {"answer": "We recommend transparent disclosure at the start of the call. In practice callers care most about being answered immediately and getting the task done, and the agent hands over to a person on request.", "question": "Will callers know they are talking to AI?"}, {"answer": "Yes, for well-defined, repetitive call types such as status checks, bookings, opening hours, basic troubleshooting and routing. Complex or sensitive cases are escalated to your team with context.", "question": "Can AI automate customer support calls?"}, {"answer": "Yes. The agent can check live availability, book the slot, send a confirmation and add the appointment to your calendar or booking system.", "question": "Can it book appointments in our calendar?"}, {"answer": "It follows your escalation rules, warm transfer to a team member, callback scheduling, or taking a message with a summary sent to your inbox and CRM.", "question": "What happens if the bot cannot help?"}], "name": "Voice Bot Solutions", "slug": "voice-bot-solutions", "image": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787043903136-44wv0-voice-bot-solutions.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MDQzOTAzMTM2LTQ0d3YwLXZvaWNlLWJvdC1zb2x1dGlvbnMud2VicCIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODcwNDM5MDMsImV4cCI6MTk0NDcyMzkwM30.hXY_RCZu7MGsH98SoWGkDmHVLBND2X0Gjflp1VTss48", "steps": [{"title": "Scope", "description": "Choose the call types to automate first."}, {"title": "Script design", "description": "Conversation, tone and escalation rules."}, {"title": "Build", "description": "Voice agent, telephony and integrations."}, {"title": "Test", "description": "Accent, noise and edge-case testing."}, {"title": "Go live", "description": "Phased rollout with overflow routing."}, {"title": "Tune", "description": "Improve from real call transcripts."}], "ctaCopy": "Tell us your call volume and we will scope a voice agent that fits.", "eyebrow": "AI & Automation", "related": ["chatbot-solutions", "whatsapp-automation", "mobile-development"], "audience": "Clinics, service businesses, real estate teams, education providers and any business losing revenue to unanswered calls.", "basePath": "/ai-solutions", "benefits": [{"title": "Zero missed calls", "description": "Every caller is answered immediately."}, {"title": "Freed-up staff", "description": "Routine calls handled without a person."}, {"title": "Fuller calendar", "description": "Booking and confirmation automated."}, {"title": "Complete visibility", "description": "Transcripts reveal what callers really want."}], "category": "ai", "features": ["Natural voice and interruption handling", "Multi-language support", "Business-hours and overflow routing", "Calendar availability checks", "Call summaries to email or CRM", "Configurable escalation rules"], "heroCopy": "A natural-sounding voice agent that handles routine calls, captures details and transfers the ones that matter to a human.", "imageAlt": "voice-bot-solutions", "problems": ["Calls ring out during busy hours and after close", "Reception time is consumed by routine questions", "Appointment confirmations take hours of manual dialling", "No record of what callers actually asked", "Peak-season call volume cannot be staffed economically"], "seoTitle": "AI Voice Bot Solutions | Automated Call Handling | Work With Vrajesh", "useCases": ["After-hours call answering", "Appointment booking and rescheduling", "Order status and delivery queries", "Lead qualification before sales callback", "Payment and renewal reminders", "Overflow handling during peak hours"], "solutions": ["Inbound answering with natural conversation and your script", "Caller qualification and intent capture", "Appointment booking and confirmation calls", "Warm transfer to the right team member", "Transcripts, summaries and CRM logging"], "primaryCta": {"href": "/contact", "label": "Automate My Calls"}, "techGroups": [{"group": "Voice AI", "items": ["Speech-to-text", "LLM conversation", "Text-to-speech", "Turn detection"]}, {"group": "Telephony", "items": ["SIP / VoIP", "Call forwarding", "IVR replacement", "Warm transfer"]}, {"group": "Integrations", "items": ["Calendars", "CRM", "Ticketing", "REST APIs"]}], "cardSummary": "AI voice agents that answer calls, qualify callers and book appointments naturally.", "ctaHeadline": "Stop losing business to missed calls", "deliverables": [{"title": "Inbound call handling", "description": "The agent answers instantly, every time."}, {"title": "Outbound reminders", "description": "Confirmation and follow-up calls at scale."}, {"title": "Call qualification", "description": "Structured questions before transfer."}, {"title": "Appointment booking", "description": "Slots checked and confirmed on the call."}, {"title": "Human transfer", "description": "Escalation rules with context."}, {"title": "Transcripts & analytics", "description": "Every call recorded, summarised and searchable."}], "directAnswer": "An AI voice bot is a conversational agent that answers or places phone calls, understands natural speech, responds in a human-like voice, completes tasks such as booking or qualification, and transfers to a person when needed, logging transcripts to your systems.", "problemIntro": "Missed calls are missed revenue, and most businesses miss a lot of them.", "categoryLabel": "AI & Automation", "solutionIntro": "We deploy a voice agent scoped to specific, high-volume call types.", "showOnHomepage": false, "metaDescription": "AI voice bot solutions that answer inbound calls, qualify callers, book appointments, confirm orders and transfer to your team, with transcripts and CRM logging."}', '2026-08-17 14:06:34', '2026-08-18 09:05:09', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4739e18c-3df4-4f26-97b7-24e723d9a96f', 'case_studies', 'ecommerce-presales-assistant-usa', 21, 'published', '{"slug": "ecommerce-presales-assistant-usa", "team": "1 AI engineer, 1 conversation designer, 1 developer", "title": "A pre-sales assistant that helps shoppers choose the right product", "country": "United States", "metrics": [], "features": ["Live catalogue and stock awareness", "Guided sizing and compatibility flows", "In-chat add-to-cart", "Authenticated order status lookups", "Escalation to human sales with cart context"], "industry": "E-commerce", "outcomes": ["Shoppers get compatibility answers without leaving the product page", "Evening and weekend questions no longer wait for office hours", "Sales agents receive escalations with the cart and history attached"], "solution": [{"title": "Product-data grounding", "description": "The assistant reads the live catalogue, specifications, compatibility matrix and stock, rather than static text."}, {"title": "Guided selection flows", "description": "Short question paths for sizing and compatibility that end in a specific recommendation."}, {"title": "Add-to-cart handoff", "description": "Recommended items added directly to cart with the reasoning shown to the shopper."}, {"title": "Order-status coverage", "description": "Authenticated order lookups so post-purchase questions never reach the sales queue."}], "challenge": "Shoppers abandoned carts over questions the product page never answered: whether an accessory fits their model, which size to choose, and when a backordered item ships. Email replies arrived a day later when the purchase intent had gone, and the phone line only ran during office hours.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787117793696-rw6xt-8f7c3d6b-2267-4832-a43b-863cf1b830b0.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTE3NzkzNjk2LXJ3Nnh0LThmN2MzZDZiLTIyNjctNDgzMi1hNDNiLTg2M2NmMWI4MzBiMC53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzExNzc5MywiZXhwIjoxOTQ0Nzk3NzkzfQ.dLlhC1pFY0fVjnKl6gTael0N7mS---ZjCYaSx2GxTn0", "valueProp": "Answer the question that stands between browsing and buying.", "afterState": ["Instant product guidance", "Session-time answers", "24/7 coverage", "Assisted checkout"], "clientName": "Stephen", "objectives": ["Answer purchase-blocking questions instantly", "Recommend accurately from real product data", "Capture the sale within the same session"], "serviceKey": "chatbot-solutions", "beforeState": ["Unanswered pre-sales questions", "Delayed email replies", "Office-hours-only support", "Abandoned carts"], "countryCode": "us", "placeholder": true, "publishedDate": "2025-12-08", "challengePoints": ["Compatibility and sizing questions unanswered at the decision point", "Next-day email replies missing the buying window", "No support coverage during peak evening shopping hours"], "projectDuration": "8 weeks", "clientDescriptor": "Specialty equipment retailer", "shortDescription": "Sizing, compatibility and stock questions answered in the moment of decision, with the recommendation added straight to cart."}', '2026-08-17 14:05:37', '2026-08-19 05:37:27', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('efe873c2-53e5-456b-8f94-68ef022d6890', 'case_studies', 'legal-intake-voice-bot-canada', 32, 'published', '{"slug": "legal-intake-voice-bot-canada", "team": "1 AI engineer, 1 conversation designer, 1 telephony engineer", "title": "After-hours call intake for a law firm", "country": "Canada", "metrics": [], "featured": true, "features": ["24/7 conversational call answering", "Structured matter intake", "Urgent-matter escalation to the duty lawyer", "Consultation booking during the call", "Transcript and summary in the practice system"], "industry": "Legal services", "outcomes": ["Every after-hours caller has a conversation instead of a beep", "Lawyers start callbacks with the matter details already captured", "Urgent matters are flagged the moment the call ends"], "solution": [{"title": "Natural intake conversation", "description": "A clearly identified AI assistant that gathers matter type, timeline and contact details conversationally."}, {"title": "Urgency routing", "description": "Time-critical matters trigger an immediate alert to the duty lawyer rather than a morning summary."}, {"title": "Conflict-safe scope", "description": "The assistant never gives legal opinions; it collects information and books consultations only."}, {"title": "Practice system integration", "description": "Every call transcribed, summarised and filed as a prospective matter record."}], "challenge": "Calls outside office hours went to voicemail, and most callers hung up without leaving a message, in legal services, people who need help usually call the next firm on the list. Messages that were left often lacked the basic details needed to call back usefully, and urgent matters were indistinguishable from routine ones.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787124115933-hh8z6-2aaf9ca2-4ea