INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('e9c90717-8f20-4c27-a08e-df08f8e75230', 'case_studies', 'beauty-clinic-dm-booking-uae', 29, 'published', '{"slug": "beauty-clinic-dm-booking-uae", "team": "1 automation engineer, 1 conversation designer", "title": "DM-to-booking automation for an aesthetics clinic", "country": "United Arab Emirates", "metrics": [], "features": ["Automated DM qualification flows", "Clinical escalation rules", "In-DM consultation booking", "Price and package information delivery", "CRM logging of every enquiry"], "industry": "Beauty & wellness", "outcomes": ["Every DM gets an immediate, accurate first response", "Medical suitability questions always reach clinical staff", "Consultations are booked without the front desk coordinating"], "solution": [{"title": "Treatment-aware qualification", "description": "Automated flows collect treatment interest, prior history and preferred branch before booking."}, {"title": "Clinical guardrails", "description": "Suitability and medical questions are never auto-answered; they route to clinical staff with context."}, {"title": "Consultation booking", "description": "Calendar-integrated booking completed inside the DM thread with confirmations."}, {"title": "Follow-up sequences", "description": "Reminders for unbooked enquiries and post-consultation check-ins."}], "challenge": "Instagram was the clinic''s main discovery channel, and almost every enquiry started as a DM about price or suitability. The front desk answered between patients, so replies were slow and inconsistent, and treatment questions were sometimes answered by non-clinical staff, a real risk in a regulated space.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787125919394-aempe-b822aa93-a5de-412e-ae14-6740e63a0675.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNG