INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('ba490df1-bfbf-4648-a27f-c64d6358125e', 'service_faqs', 'website-development-how-long-does-it-take-to-build-a-website', 1, 'published', '{"answer": "A focused landing page typically takes 1\\u20132 weeks. A business website usually takes 3\\u20136 weeks. Web applications, e-commerce and SaaS platforms depend on scope and are planned in phases after discovery.", "service": "website-development", "question": "How long does it take to build a website?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('6f67b880-bc32-48d6-aec0-c5644fdedbbf', 'service_faqs', 'website-development-which-technologies-do-you-use-for-websit', 2, 'published', '{"answer": "Frontend work uses React, Next.js, Angular, TypeScript, HTML and CSS. Backend work uses Node.js, .NET, ASP.NET Core, C#, Python and REST APIs. Databases include SQL Server, PostgreSQL, MySQL, MongoDB and Supabase.", "service": "website-development", "question": "Which technologies do you use for website development?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('ae65a1d7-9c5c-4397-9bfc-0734f68b200c', 'service_faqs', 'website-development-can-you-build-fully-custom-websites', 3, 'published', '{"answer": "Yes. Every build starts from your brand, audience and commercial goals. We do not resell themes. We build a design system and component library specific to your business.", "service": "website-development", "question": "Can you build fully custom websites?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('97f80ff5-ff9d-455e-aecf-f768ce4821fc', 'service_faqs', 'website-development-can-you-integrate-third-party-apis-and-c', 4, 'published', '{"answer": "Yes. We regularly integrate CRMs, payment gateways, email platforms, analytics, booking systems, ERPs and internal APIs, including secure server-side integrations.", "service": "website-development", "question": "Can you integrate third-party APIs and CRMs?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('1414b69a-4157-4f68-9a8f-42735f32c70e', 'service_faqs', 'website-development-will-the-website-be-seo-friendly', 5, 'published', '{"answer": "Yes. Unique metadata, semantic headings, canonical URLs, sitemap, robots rules, structured data, image alt text, internal linking and Core Web Vitals optimisation are part of the build.", "service": "website-development", "question": "Will the website be SEO friendly?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('d228f438-d860-4563-9772-0f91b9dace90', 'service_faqs', 'mobile-development-should-i-choose-flutter-or-react-native', 6, 'published', '{"answer": "Flutter suits highly custom, animation-rich interfaces with consistent rendering across platforms. React Native suits teams already invested in the JavaScript and React ecosystem or sharing logic with a web app. We recommend based on your team, timeline and feature set.", "service": "mobile-development", "question": "Should I choose Flutter or React Native?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('aad05ae3-65c5-4f20-aa5a-3914df6a81ff', 'service_faqs', 'mobile-development-can-one-app-work-on-both-android-and-ios', 7, 'published', '{"answer": "Yes. Cross-platform frameworks share a single codebase across both platforms while still allowing native modules where a platform-specific capability is required.", "service": "mobile-development", "question": "Can one app work on both Android and iOS?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('5835a14b-e135-4d74-b056-efae8a06bf0f', 'service_faqs', 'mobile-development-can-you-add-payments-and-subscriptions', 8, 'published', '{"answer": "Yes. We integrate payment gateways and in-app purchase or subscription flows, including receipts, refunds handling and store compliance requirements.", "service": "mobile-development", "question": "Can you add payments and subscriptions?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
