INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4550e9df-e7b3-4cc4-bd36-7e06c237652e', 'service_faqs', 'mobile-development-can-the-app-connect-to-our-existing-syste', 10, 'published', '{"answer": "Yes. We connect apps to existing REST APIs, CRMs, ERPs and databases, or build a new backend using Node.js, .NET, Firebase or Supabase.", "service": "mobile-development", "question": "Can the app connect to our existing systems?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('e3cf11fe-fcb5-4e3a-b838-df34be1e2868', 'service_faqs', 'social-media-marketing-what-does-a-social-media-marketing-se', 11, 'published', '{"answer": "Strategy, content pillars, a monthly calendar, creative production (reels, carousels, statics), publishing, community management and monthly performance reporting.", "service": "social-media-marketing", "question": "What does a social media marketing service include?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('ca21f695-28f0-42c2-ae71-23be12da1694', 'service_faqs', 'social-media-marketing-how-many-posts-should-a-business-publ', 12, 'published', '{"answer": "Consistency matters more than volume. Most businesses see traction with 12\\u201320 quality assets per month, weighted toward short-form video, published on a predictable schedule.", "service": "social-media-marketing", "question": "How many posts should a business publish per month?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4778371e-8fbd-406c-a51b-f7b3177d2677', 'service_faqs', 'social-media-marketing-how-long-before-social-media-produces', 13, 'published', '{"answer": "Reach and engagement usually shift within 4\\u20136 weeks. Inquiry volume typically becomes stable around month three, once content pillars and the best-performing formats are identified.", "service": "social-media-marketing", "question": "How long before social media produces results?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4c6875ca-1f1b-491b-8b3b-7e5b9e161f5a', 'service_faqs', 'social-media-marketing-do-you-create-the-content-or-only-sch', 14, 'published', '{"answer": "We create it. Scripting, design, editing and captions are handled in-house, with your input on offers, product detail and approvals.", "service": "social-media-marketing", "question": "Do you create the content or only schedule it?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('3bcf2e2a-4f23-47c4-bb3c-1624b608917e', 'service_faqs', 'social-media-marketing-can-social-media-generate-actual-lead', 15, 'published', '{"answer": "Yes, when content answers buyer questions and each post has a clear next step. Pairing organic content with DM automation and Meta Ads shortens the path from attention to inquiry.", "service": "social-media-marketing", "question": "Can social media generate actual leads?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('be4f0f20-f1d2-4657-84e5-be1e533bc4d4', 'service_faqs', 'chatbot-solutions-can-it-connect-to-our-crm', 34, 'published', '{"answer": "Yes. Conversations, contact details and qualification data can be pushed to your CRM, email or internal tools automatically through APIs or webhooks.", "service": "chatbot-solutions", "question": "Can it connect to our CRM?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('563553a0-a833-40ff-a6b6-b942840b3eb4', 'service_faqs', 'linkedin-personal-branding-what-is-linkedin-personal-brandin', 16, 'published', '{"answer": "It is the process of positioning a person, usually a founder or expert, so their profile and content consistently communicate who they help, how they help and why they are credible, which turns LinkedIn into an inbound channel.", "service": "linkedin-personal-branding", "question": "What is LinkedIn personal branding?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('fb3e3ef5-0059-4ed5-9ad6-cb7d534e13b3', 'service_faqs', 'linkedin-personal-branding-how-can-linkedin-personal-brandin', 17, 'published', '{"answer": "People trust people faster than brands. A founder publishing consistently shortens sales cycles, creates warm inbound conversations, supports the sales team''s outreach and improves hiring and partnership opportunities.", "service": "linkedin-personal-branding", "question": "How can LinkedIn personal branding help a business?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('c4ecb001-4c52-4247-bf41-f5da173509b4', 'service_faqs', 'linkedin-personal-branding-what-should-founders-post-on-link', 18, 'published', '{"answer": "Client problems and how they were solved, lessons from delivery, industry opinions, behind-the-scenes decisions, frameworks you use, and occasional clear offers. Aim for roughly 80% value and 20% direct offer.", "service": "linkedin-personal-branding", "question": "What should founders post on LinkedIn?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('9009d2b1-e4a9-4ced-a40f-bf359bde2c1d', 'service_faqs', 'linkedin-personal-branding-can-linkedin-personal-branding-ge', 19, 'published', '{"answer": "Yes. Consistent, buyer-focused posting combined with targeted engagement generates profile views, DMs and inbound inquiries. Results typically build over 60\\u201390 days of steady publishing.", "service": "linkedin-personal-branding", "question": "Can LinkedIn personal branding generate leads?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('5ee5aa88-fa02-4e61-a9db-6511402f7d5f', 'service_faqs', 'linkedin-personal-branding-will-the-posts-sound-like-me', 20, 'published', '{"answer": "Yes. We start with voice interviews and existing material, then draft in your language. You review every post before it goes live.", "service": "linkedin-personal-branding", "question": "Will the posts sound like me?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('d93c3cff-62c0-4247-924f-9bf9d27f387e', 'service_faqs', 'email-marketing-is-email-marketing-still-effective', 21, 'published', '{"answer": "Yes. Email remains one of the highest-return channels because you own the audience, messaging can be personalised by segment, and automated flows keep working without ongoing ad spend.", "service": "email-marketing", "question": "Is email marketing still effective?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('eb78ddab-8062-424a-a8e2-f72cba73be4c', 'service_faqs', 'email-marketing-how-do-you-keep-emails-out-of-spam', 22, 'published', '{"answer": "Through authenticated domains (SPF, DKIM, DMARC), gradual sending warm-up, clean and consented lists, sensible sending volume, plain readable formatting and honest subject lines.", "service": "email-marketing", "question": "How do you keep emails out of spam?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('435f027d-23c6-4e5e-bd57-c76c792c5af0', 'service_faqs', 'email-marketing-what-is-the-difference-between-nurture-and-c', 23, 'published', '{"answer": "Nurture email goes to contacts who already engaged with you and focuses on education and confidence. Cold email reaches new prospects who have not engaged and must be highly targeted, short and relevance-led.", "service": "email-marketing", "question": "What is the difference between nurture and cold email?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('2f259aaf-dd01-495a-9a7d-e02915330d04', 'service_faqs', 'email-marketing-which-email-flows-should-an-e-commerce-brand', 24, 'published', '{"answer": "Welcome, abandoned cart, browse abandonment, post-purchase and win-back. These five flows usually cover the majority of automated email revenue.", "service": "email-marketing", "question": "Which email flows should an e-commerce brand start with?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('03e17fcf-901a-4cd9-ba1d-76b2a1dd0c39', 'service_faqs', 'email-marketing-do-you-write-the-emails', 25, 'published', '{"answer": "Yes. Strategy, copy, design, automation build and reporting are included. You approve messaging before anything is sent.", "service": "email-marketing", "question": "Do you write the emails?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('6b966f7a-08dc-41f8-b879-ed936c17c1d9', 'service_faqs', 'meta-ads-how-much-should-i-budget-for-meta-ads', 26, 'published', '{"answer": "Enough to gather learning data. For most lead-generation businesses that means a test budget that can produce at least 30\\u201350 conversions per month; scaling decisions follow once cost per qualified lead is known.", "service": "meta-ads", "question": "How much should I budget for Meta Ads?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('76c53dc8-214a-4d86-bb6c-320590880b3e', 'service_faqs', 'meta-ads-how-long-until-meta-ads-produce-results', 27, 'published', '{"answer": "Campaigns typically need 2\\u20133 weeks to exit the learning phase and identify winning creative. Meaningful optimisation decisions are usually possible by week four.", "service": "meta-ads", "question": "How long until Meta Ads produce results?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4a12c755-4fc5-4639-880c-1ed766f66495', 'service_faqs', 'meta-ads-why-are-my-leads-low-quality', 28, 'published', '{"answer": "Usually the offer is too broad, the form is too easy to complete, or the ad promises something the landing page does not. Adding qualification questions and tightening the message improves quality quickly.", "service": "meta-ads", "question": "Why are my leads low quality?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('99f2b704-4ff5-4f73-babb-e6d09556f89d', 'service_faqs', 'meta-ads-do-you-also-make-the-ad-creative', 29, 'published', '{"answer": "Yes. We plan and produce video and static creative, including hooks, scripts and copy, because creative is the main lever on Meta performance.", "service": "meta-ads", "question": "Do you also make the ad creative?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4a12fe4c-f7e6-444c-99f9-b5144b512aa0', 'service_faqs', 'meta-ads-do-i-need-a-landing-page-for-meta-ads', 30, 'published', '{"answer": "Not always. Instant forms work well for simple offers. For higher-value services or e-commerce, a dedicated landing page usually converts better and gives more control over qualification.", "service": "meta-ads", "question": "Do I need a landing page for Meta Ads?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('26de01d3-37df-46d3-b662-b45c5770d162', 'service_faqs', 'chatbot-solutions-what-can-an-ai-chatbot-automate', 31, 'published', '{"answer": "It can answer product and service questions, qualify leads, capture contact details, book appointments, share documents, provide order or status updates, and escalate anything complex to a human with full context.", "service": "chatbot-solutions", "question": "What can an AI chatbot automate?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('3d1d46a3-c762-40cf-ab78-9096f22bd156', 'service_faqs', 'chatbot-solutions-can-ai-qualify-leads-reliably', 32, 'published', '{"answer": "Yes. The bot asks the same qualification questions your sales team would ask, covering need, timeline, budget range and decision role, then scores or routes the lead accordingly, so your team only spends time on real opportunities.", "service": "chatbot-solutions", "question": "Can AI qualify leads reliably?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('aab36d2e-163d-4a32-be26-51af0b38119f', 'service_faqs', 'chatbot-solutions-will-the-chatbot-invent-answers', 33, 'published', '{"answer": "We restrict the assistant to your approved knowledge base with explicit guardrails. When it cannot answer confidently, it says so and offers human handover instead of guessing.", "service": "chatbot-solutions", "question": "Will the chatbot invent answers?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('7409323b-cba2-41a0-80a0-ad5916ca7522', 'service_faqs', 'chatbot-solutions-how-long-does-chatbot-deployment-take', 35, 'published', '{"answer": "A focused website chatbot with qualification and booking typically takes 1\\u20133 weeks depending on how much source content and how many integrations are involved.", "service": "chatbot-solutions", "question": "How long does chatbot deployment take?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('bb399d63-b6d7-4ca4-95e0-47c9efadd428', 'service_faqs', 'whatsapp-automation-how-can-whatsapp-automation-help-a-busin', 36, 'published', '{"answer": "It gives every customer an instant reply, qualifies enquiries automatically, sends reminders and updates without manual effort, and keeps the whole conversation history in one place, which usually improves response time, show-up rate and conversion.", "service": "whatsapp-automation", "question": "How can WhatsApp automation help a business?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('dafdfb32-a040-417d-9234-b73182daa362', 'service_faqs', 'whatsapp-automation-do-i-need-the-whatsapp-business-api', 37, 'published', '{"answer": "For automation at scale, yes. The free Business app is limited to manual use on one device. The official API supports automation, multiple agents, templates, integrations and reliable delivery.", "service": "whatsapp-automation", "question": "Do I need the WhatsApp Business API?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('0a4b8d3c-c686-4104-82b9-cff18ce204a6', 'service_faqs', 'whatsapp-automation-is-whatsapp-automation-compliant', 38, 'published', '{"answer": "Yes, when built correctly. We use the official API, opt-in collection and approved message templates for business-initiated messages, so your number stays in good standing.", "service": "whatsapp-automation", "question": "Is WhatsApp automation compliant?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('421b42f7-09b0-410f-ac3a-f18579f54d5b', 'service_faqs', 'whatsapp-automation-can-a-human-take-over-the-conversation', 39, 'published', '{"answer": "Yes. Any conversation can be escalated to a team member in a shared inbox, with full context, and automation can be paused for that contact.", "service": "whatsapp-automation", "question": "Can a human take over the conversation?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('55179cd3-0c3d-418d-aac9-ffff0a257fb2', 'service_faqs', 'whatsapp-automation-can-whatsapp-connect-to-our-crm', 40, 'published', '{"answer": "Yes. Leads, tags and conversation summaries can sync to your CRM, and the bot can pull order or booking data from your systems to answer accurately.", "service": "whatsapp-automation", "question": "Can WhatsApp connect to our CRM?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('7fb86805-058f-4290-842a-67af18fa0f27', 'service_faqs', 'facebook-automation-what-is-facebook-automation', 41, 'published', '{"answer": "It is the use of AI and rule-based flows on Facebook Messenger, page comments and Instagram DMs to reply instantly, answer common questions, collect contact details and route qualified conversations to your team.", "service": "facebook-automation", "question": "What is Facebook automation?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('034558a2-02e9-4a74-acbf-8654d0d4640b', 'service_faqs', 'facebook-automation-can-comments-be-answered-automatically', 42, 'published', '{"answer": "Yes. Keyword triggers can post a public reply and simultaneously send a private message with details, pricing or a booking link, which is especially effective on ad posts.", "service": "facebook-automation", "question": "Can comments be answered automatically?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('ba2aeea2-0a6b-49f7-bd0a-6915d78a0d57', 'service_faqs', 'facebook-automation-does-automation-affect-ad-performance', 43, 'published', '{"answer": "It usually improves it. Faster first response and structured qualification increase the share of ad clicks that become contactable leads, which lowers effective cost per qualified lead.", "service": "facebook-automation", "question": "Does automation affect ad performance?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('24e81f05-8055-45c7-ab10-f7d570a1a734', 'service_faqs', 'facebook-automation-is-it-against-meta-s-policies', 44, 'published', '{"answer": "No, when built on official Meta platform tools and within messaging policy windows and opt-in rules. We design flows that respect those limits.", "service": "facebook-automation", "question": "Is it against Meta''s policies?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('6b06f522-a015-48eb-a36a-5f783782ca40', 'service_faqs', 'facebook-automation-can-it-work-together-with-whatsapp-autom', 45, 'published', '{"answer": "Yes. Many businesses run Facebook and Instagram automation alongside WhatsApp automation so every Meta channel shares the same qualification logic and CRM destination.", "service": "facebook-automation", "question": "Can it work together with WhatsApp automation?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('a227ceb8-c034-481a-babe-242edb89bdf2', 'service_faqs', 'voice-bot-solutions-what-is-an-ai-voice-bot', 46, 'published', '{"answer": "It is a phone agent powered by speech recognition and conversational AI. It understands what a caller says, replies in a natural voice, completes tasks like booking or qualification, and transfers to a human when the request needs one.", "service": "voice-bot-solutions", "question": "What is an AI voice bot?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('42cc72f0-7338-4a0a-8087-fece65855b63', 'service_faqs', 'voice-bot-solutions-will-callers-know-they-are-talking-to-ai', 47, 'published', '{"answer": "We recommend transparent disclosure at the start of the call. In practice callers care most about being answered immediately and getting the task done, and the agent hands over to a person on request.", "service": "voice-bot-solutions", "question": "Will callers know they are talking to AI?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('575de617-51d1-4a4b-a096-932ce90cfe4c', 'service_faqs', 'voice-bot-solutions-can-ai-automate-customer-support-calls', 48, 'published', '{"answer": "Yes, for well-defined, repetitive call types such as status checks, bookings, opening hours, basic troubleshooting and routing. Complex or sensitive cases are escalated to your team with context.", "service": "voice-bot-solutions", "question": "Can AI automate customer support calls?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('ef28d08e-21c5-4741-b135-72c096e6f569', 'service_faqs', 'voice-bot-solutions-can-it-book-appointments-in-our-calendar', 49, 'published', '{"answer": "Yes. The agent can check live availability, book the slot, send a confirmation and add the appointment to your calendar or booking system.", "service": "voice-bot-solutions", "question": "Can it book appointments in our calendar?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('69630c06-8f7a-4064-a74a-68e90ea57d1f', 'service_faqs', 'voice-bot-solutions-what-happens-if-the-bot-cannot-help', 50, 'published', '{"answer": "It follows your escalation rules: warm transfer to a team member, callback scheduling, or taking a message with a summary sent to your inbox and CRM.", "service": "voice-bot-solutions", "question": "What happens if the bot cannot help?"}', '2026-08-18 07:12:47', '2026-08-18 07:12:47', NULL);
