"useCases": ["A B2B firm nurturing leads over a 90-day cycle", "An online store recovering abandoned carts", "A SaaS product onboarding trial users", "An agency running targeted cold outreach", "A clinic sending appointment and recall reminders"], "solutions": ["Lifecycle map: acquisition, nurture, conversion, retention", "Deliverability setup with SPF, DKIM and DMARC guidance", "Segment-specific copy instead of one-size-fits-all blasts", "Automated triggers based on behaviour and CRM stage", "Ongoing testing of subject lines, offers and timing"], "primaryCta": {"href": "/contact", "label": "Automate My Follow-Ups"}, "techGroups": [{"group": "Platforms", "items": ["Mailchimp", "Klaviyo", "Brevo", "HubSpot", "Resend"]}, {"group": "Deliverability", "items": ["SPF", "DKIM", "DMARC", "Domain warm-up", "List hygiene"]}, {"group": "Integrations", "items": ["CRM", "E-commerce", "Web forms", "Analytics"]}], "cardSummary": "Lifecycle email, cold outreach and automated follow-ups that recover revenue.", "ctaHeadline": "Stop losing leads to silence", "deliverables": [{"title": "Email strategy", "description": "Lifecycle map, segments, offers and cadence."}, {"title": "Cold email campaigns", "description": "Targeted outreach with warm-up and reply handling."}, {"title": "Lead nurturing", "description": "Educational sequences that build buying confidence."}, {"title": "Automation", "description": "Behaviour and stage triggered flows in your platform."}, {"title": "Follow-up sequences", "description": "Structured multi-touch follow-up after inquiries."}, {"title": "Retention campaigns", "description": "Win-back, reorder and loyalty programmes."}, {"title": "E-commerce email marketing", "description": "Welcome, browse, cart and post-purchase flows."}], "directAnswer": "Email marketing is the strategy, copywriting, automation and measurement of email campaigns, from cold outreach and lead nurture to onboarding, retention and e-commerce lifecycle flows.", "problemIntro": "The database is the most underused asset in most businesses.", "categoryLabel": "Marketing & Growth", "homepageOrder": 3, "solutionIntro": "We design email as a system that runs whether or not anyone remembers to send it.", "showOnHomepage": true, "metaDescription": "Email marketing services covering strategy, cold email, lead nurturing, automation, follow-up sequences, retention campaigns and e-commerce email flows."}', '2026-08-17 14:06:34', '2026-08-18 08:39:47', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('4cf1906a-fd5e-484d-acde-89a19e819089', 'services', 'meta-ads', 5, 'published', '{"h1": "Facebook & Instagram Ads Judged on Qualified Leads", "faqs": [{"answer": "Enough to gather learning data. For most lead-generation businesses that means a test budget that can produce at least 30\\u201350 conversions per month; scaling decisions follow once cost per qualified lead is known.", "question": "How much should I budget for Meta Ads?"}, {"answer": "Campaigns typically need 2\\u20133 weeks to exit the learning phase and identify winning creative. Meaningful optimisation decisions are usually possible by week four.", "question": "How long until Meta Ads produce results?"}, {"answer": "Usually the offer is too broad, the form is too easy to complete, or the ad promises something the landing page does not. Adding qualification questions and tightening the message improves quality quickly.", "question": "Why are my leads low quality?"}, {"answer": "Yes. We plan and produce video and static creative, including hooks, scripts and copy, because creative is the main lever on Meta performance.", "question": "Do you also make the ad creative?"}, {"answer": "Not always, instant forms work well for simple offers. For higher-value services or e-commerce, a dedicated landing page usually converts better and gives more control over qualification.", "question": "Do I need a landing page for Meta Ads?"}], "name": "Meta Ads", "slug": "meta-ads", "image": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787042434443-fh7yg-meta-ads.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MDQyNDM0NDQzLWZoN3lnLW1ldGEtYWRzLndlYnAiLCJzY29wZSI6ImRvd25sb2FkIiwiaWF0IjoxNzg3MDQyNDM0LCJleHAiOjE5NDQ3MjI0MzR9.M16i00cYuLZPbLYojtshdMDzCX6pkS3YoW2vpQPiVGs", "steps": [{"title": "Audit", "description": "Account, tracking, creative and offer review."}, {"title": "Setup", "description": "Structure, tracking and audience build."}, {"title": "Launch", "description": "First test round across hooks and formats."}, {"title": "Learn", "description": "Identify winning angles and cut waste."}, {"title": "Scale", "description": "Increase budget on proven combinations."}, {"title": "Report", "description": "Cost per lead, quality and pipeline impact."}], "ctaCopy": "Send your current results and we will tell you what to change first.", "eyebrow": "Marketing & Growth", "related": ["social-media-marketing", "website-development", "facebook-automation"], "audience": "Local businesses, service providers, e-commerce brands and lead-generation businesses ready to invest in consistent paid acquisition.", "basePath": "/services", "benefits": [{"title": "Predictable lead flow", "description": "A channel you can turn up when needed."}, {"title": "Lower cost per lead", "description": "Creative testing beats audience guessing."}, {"title": "Better lead quality", "description": "Qualification built into the funnel."}, {"title": "Full visibility", "description": "Reporting tied to real business results."}], "category": "marketing", "features": ["Meta Pixel and Conversions API setup", "UTM and CRM attribution", "Creative test matrix", "Landing page conversion review", "Weekly and monthly reporting", "Lead quality feedback loop"], "heroCopy": "Structured campaigns, disciplined creative testing and clean tracking, so spend is tied to pipeline, not impressions.", "imageAlt": "meta-ads", "problems": ["Boosted posts with no campaign objective", "One creative running until it fatigues", "Leads arrive unqualified and waste sales time", "Broken or missing conversion tracking", "No retargeting for warm audiences"], "seoTitle": "Meta Ads Services | Facebook & Instagram Advertising | Work With Vrajesh", "useCases": ["A real estate team generating site-visit bookings", "A clinic filling appointment slots locally", "An e-commerce brand scaling profitable purchases", "A B2B firm running lead-magnet campaigns", "An education brand driving admission inquiries"], "solutions": ["Offer and message clarity before any spend", "Clean account structure by objective and funnel stage", "Creative testing framework across hooks, formats and angles", "Pixel, Conversions API and event tracking verified", "Retargeting ladders for site, video and engagement audiences"], "primaryCta": {"href": "/contact", "label": "Plan My Ad Campaign"}, "techGroups": [{"group": "Platform", "items": ["Meta Ads Manager", "Meta Pixel", "Conversions API", "Meta Business Suite"]}, {"group": "Tracking", "items": ["GA4", "UTM parameters", "CRM attribution", "Event tracking"]}, {"group": "Creative", "items": ["Short-form video", "Static creative", "UGC-style ads", "Ad copywriting"]}], "cardSummary": "Facebook and Instagram advertising built around creative testing and cost per qualified lead.", "ctaHeadline": "Make paid ads accountable", "deliverables": [{"title": "Facebook Ads", "description": "Campaigns built by objective, not boosted posts."}, {"title": "Instagram Ads", "description": "Feed, story and reels placements with native creative."}, {"title": "Lead generation", "description": "Instant forms and landing pages with qualification questions."}, {"title": "Retargeting", "description": "Warm-audience sequences that recover lost interest."}, {"title": "Conversion campaigns", "description": "Purchase and inquiry optimisation with clean tracking."}, {"title": "Audience research", "description": "Interest, lookalike and custom audience mapping."}, {"title": "Creative strategy", "description": "Hooks, angles and formats planned as a test matrix."}, {"title": "Optimisation", "description": "Weekly reviews, budget shifts and scaling decisions."}], "directAnswer": "Meta Ads is paid advertising across Facebook and Instagram, covering audience research, creative strategy, campaign structure, conversion tracking, retargeting and ongoing optimisation toward a defined cost per result.", "problemIntro": "Most ad accounts fail on structure and creative, not budget.", "categoryLabel": "Marketing & Growth", "solutionIntro": "We rebuild the account around a clear testing and scaling system.", "metaDescription": "Meta Ads management for Facebook and Instagram, audience research, creative strategy, lead generation, retargeting, conversion campaigns and continuous optimisation."}', '2026-08-17 14:06:34', '2026-08-18 08:40:38', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('933c6eff-e7aa-4740-a86d-be5c6a185c08', 'service_faqs', 'website-development-what-does-website-development-include', 0, 'published', '{"answer": "It includes discovery and strategy, information architecture, UI design, frontend and backend development, CMS setup, integrations, SEO and AEO implementation, performance optimisation, testing, launch and post-launch support.", "service": "website-development", "question": "What does website development include?"}', '2026-08-18 07:12:47', '2026-08-18 09:49:39', NULL);
