INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('fd92596a-28df-406c-93ca-3f0e0e564903', 'case_studies', 'clinic-appointment-automation-uae', 24, 'published', '{"slug": "clinic-appointment-automation-uae", "team": "1 automation engineer, 1 conversation designer, 1 integration developer", "title": "WhatsApp appointment automation for a multi-branch clinic", "country": "United Arab Emirates", "metrics": [], "featured": true, "features": ["Automated enquiry qualification", "In-chat booking and rescheduling", "Multi-branch calendar sync", "Reminder and preparation sequences", "Shared team inbox with CRM logging"], "industry": "Healthcare", "outcomes": ["Evening and weekend enquiries get an immediate, useful reply", "Patients reschedule themselves instead of messaging back and forth", "Every conversation is attached to the patient record"], "solution": [{"title": "Verified business messaging", "description": "Official WhatsApp Business Platform setup with approved templates and opt-in handling."}, {"title": "Booking and reschedule flows", "description": "Branch, treatment and slot selection completed inside the chat, synced with clinic calendars."}, {"title": "Reminder sequences", "description": "Confirmation, day-before and preparation reminders with one-tap reschedule."}, {"title": "Human handover", "description": "Clinical or sensitive questions handed to a named team member in a shared inbox with full history."}], "challenge": "Almost every enquiry arrived by WhatsApp on a phone at the front desk. Messages were missed during busy clinic hours, evening enquiries were answered the next morning, and no record of any conversation reached the practice management system. Reschedules were negotiated over many back-and-forth messages.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787121394798-43327-b10aa39a-d383-4bde-ab1f-f399c3d791f9.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTIxMzk0Nzk4LTQzMzI3LWIxMGFhMzlhLWQzODMtNGJkZS1hYjFmLWYzOTljM2Q3OTFmOS53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyMTM5NCwiZXhwIjoxOTQ0ODAxMzk0fQ.bG6ZtQX9uVV6rH73b1uzG5h6JFHHAf8CFAgRJPqu3Go", "valueProp": "Booking that happens where patients already message.", "afterState": ["Every enquiry captured", "24/7 automated responses", "Self-service rescheduling", "Full CRM history"], "clientName": "Saeed", "objectives": ["Capture and qualify every WhatsApp enquiry automatically", "Let patients book and reschedule without a conversation", "Log every interaction against the patient record"], "serviceKey": "whatsapp-automation", "beforeState": ["Missed messages", "Next-day replies", "Manual reschedule negotiation", "No conversation records"], "countryCode": "ae", "placeholder": true, "publishedDate": "2026-02-06", "challengePoints": ["Enquiries missed during busy clinic hours", "Evening and weekend messages answered the next working day", "No conversation history in the practice management system"], "projectDuration": "8 weeks", "clientDescriptor": "Multi-branch dental and skin clinic", "shortDescription": "Booking, rescheduling and reminders handled on the channel patients already use, with the reception desk kept in the loop."}', '2026-08-17 14:05:37', '2026-08-19 06:36:37', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('5642732b-6117-4449-b69a-5175096da550', 'case_studies', 'property-maintenance-voice-bot-uk', 34, 'published', '{"slug": "property-maintenance-voice-bot-uk", "team": "1 AI engineer, 1 conversation designer, 1 telephony engineer", "title": "Maintenance call handling for a property management company", "country": "United Kingdom", "metrics": [], "features": ["Severity-based maintenance triage", "On-call contractor dispatch automation", "Tenancy and property record matching", "Safety guidance for emergency calls", "Structured overnight reporting"], "industry": "Property management", "outcomes": ["Burst pipes get dispatched at 2am; dripping taps wait for the morning", "Tenants receive immediate safety guidance on the call", "Property managers start the day with a structured overnight summary"], "solution": [{"title": "Severity triage script", "description": "Structured questioning that distinguishes safety emergencies from routine repairs, with safety guidance given first."}, {"title": "Automatic contractor dispatch", "description": "Emergency categories trigger the on-call contractor rota with the property details attached."}, {"title": "Property record matching", "description": "Caller identification matched to the tenancy so reports file themselves correctly."}, {"title": "Morning digest", "description": "A structured overnight summary by property and severity for the management team."}], "challenge": "Tenants called about everything from a dripping tap to a burst pipe, at all hours, on the same emergency line. An outsourced answering service took messages without triage, so genuine emergencies waited alongside minor issues and property managers began each morning by unpicking a pile of unstructured notes.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787124701260-uy8uq-2032fbaf-eb15-4f3a-8d80-4cede0f4510d.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTI0NzAxMjYwLXV5OHVxLTIwMzJmYmFmLWViMTUtNGYzYS04ZDgwLTRjZWRlMGY0NTEwZC53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEyNDcwMCwiZXhwIjoxOTQ0ODA0NzAwfQ.BYb97R5OW0uYO5iW1MiroWnirsAP2X8BuQwiexifLiE", "valueProp": "Emergency triage that works at 2am.", "afterState": ["Severity-triaged calls", "Automatic emergency dispatch", "Property-matched records", "Structured morning digest"], "clientName": "Lisa", "objectives": ["Triage maintenance calls by real severity", "Dispatch genuine emergencies immediately", "Log every report against the correct property and tenancy"], "serviceKey": "voice-bot-solutions", "beforeState": ["Untriaged emergency line", "Message-taking answering service", "Delayed emergency response", "Unstructured morning backlog"], "countryCode": "gb", "placeholder": true, "publishedDate": "2025-11-28", "challengePoints": ["Emergencies and minor issues arriving on the same untriaged line", "An answering service taking messages without any assessment", "Mornings lost to reconstructing what actually happened overnight"], "projectDuration": "9 weeks", "clientDescriptor": "Residential property management company", "shortDescription": "Tenant maintenance calls triaged by severity, logged against the property and dispatched to contractors without a night-shift team."}', '2026-08-17 14:05:37', '2026-08-19 07:31:46', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('9c9f8b2d-bb1f-46a2-9a06-111e013d9511', 'case_studies', 'industrial-catalogue-migration-germany', 2, 'published', '{"slug": "industrial-catalogue-migration-germany", "team": "1 strategist, 1 designer, 2 developers, 1 SEO specialist", "title": "Bringing a 400-page industrial catalogue online without losing search visibility", "country": "Germany", "metrics": [], "features": ["Filterable component library with comparison", "Auto-generated datasheets from structured data", "Bilingual DE/EN content model", "Configuration-aware quote form", "Product and breadcrumb structured data"], "industry": "Manufacturing & B2B", "outcomes": ["Engineers can filter to the right component without contacting sales", "Quote requests arrive with the exact configuration attached", "Existing organic visibility was preserved through the migration"], "solution": [{"title": "Structured product model", "description": "Every component modelled with typed attributes so specifications become filterable data instead of documents."}, {"title": "Technical search experience", "description": "Faceted search by dimension, material, tolerance and application, with comparison view."}, {"title": "Migration with URL integrity", "description": "Full URL inventory, mapped redirects and staged rollout monitored against pre-launch rankings."}, {"title": "Self-serve enquiry path", "description": "Spec-aware quote requests that carry the exact product configuration into the sales inbox."}], "challenge": "Buyers were engineers who needed exact specifications, but the catalogue existed as hundreds of PDFs behind an unsearchable menu. The pages that did rank were old, slow and untouchable without breaking URLs. Sales received the same specification questions by email every week because the answers were locked inside downloads.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787131554447-tlpz5-5ec10605-3a68-4c3a-9d73-2c8d8f856cab.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTMxNTU0NDQ3LXRscHo1LTVlYzEwNjA1LTNhNjgtNGMzYS05ZDczLTJjOGQ4Zjg1NmNhYi53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzMTU1MywiZXhwIjoxOTQ0ODExNTUzfQ.OA-asLdKo2kwUTTfdFN8AEWHUwRJPDLynrHRqJhupXM", "valueProp": "Engineering-grade product data, finally findable.", "afterState": ["Structured product pages", "Faceted technical search", "Redirect-mapped migration", "Configured quote requests"], "clientName": "Calvin", "objectives": ["Turn PDF specifications into structured, filterable product pages", "Migrate without losing organic visibility", "Reduce repetitive technical enquiries"], "serviceKey": "website-development", "beforeState": ["PDF-only specifications", "Menu-only navigation", "Legacy URLs at risk", "Manual spec emails"], "countryCode": "de", "placeholder": true, "publishedDate": "2025-12-05", "challengePoints": ["Specifications trapped in PDFs that search engines and buyers could not use", "A decade of rankings tied to fragile legacy URLs", "Sales answering repetitive specification emails manually"], "projectDuration": "16 weeks", "clientDescriptor": "Precision components manufacturer", "shortDescription": "A decade-old technical catalogue migrated to a structured, searchable product library with its hard-earned rankings intact."}', '2026-08-17 14:05:37', '2026-08-19 09:25:56', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('935ecaed-d3af-4035-aaab-2c4b5a456eb1', 'case_studies', 'home-services-booked-visits-uk', 14, 'published', '{"slug": "home-services-booked-visits-uk", "team": "1 strategist, 1 media buyer, 1 creative designer", "title": "From cheap clicks to booked site visits for a home services brand", "country": "United Kingdom", "metrics": [], "features": ["Calendar-integrated booking funnel", "Postcode and job-type qualification", "Before-and-after creative library", "Seasonal budget pacing plan", "Capacity-aware campaign pausing"], "industry": "Home services", "outcomes": ["The team measures success by surveys booked, not enquiries received", "Out-of-area and out-of-scope enquiries are filtered before booking", "Spend follows the seasons instead of the calendar month"], "solution": [{"title": "Booking as the conversion event", "description": "Calendar bookings, not form submissions, defined as the optimisation goal end to end."}, {"title": "Geo and job-type gating", "description": "Postcode validation and job-type selection built into the funnel before booking is offered."}, {"title": "Proof-led creative", "description": "Before-and-after project footage with timeline and budget bands to set expectations."}, {"title": "Seasonal pacing", "description": "Budget pacing plan matched to historic demand curves and crew availability."}], "challenge": "Ads generated enquiries from outside the service area and for jobs the crews did not take. The calendar stayed half empty while the inbox looked busy. Seasonality was ignored, so budget ran flat through periods when nobody books renovation work.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787134717470-t9tjv-88114a0a-84d4-49b2-b39b-887bf10ca2f1.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTM0NzE3NDcwLXQ5dGp2LTg4MTE0YTBhLTg0ZDQtNDliMi1iMzliLTg4N2JmMTBjYTJmMS53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzNDcxNiwiZXhwIjoxOTQ0ODE0NzE2fQ.lJXlV9n_fzb9PJESwQJUwULvsT2eqeqvl_tjXslrMxs", "valueProp": "Campaigns that fill the survey calendar, not the inbox.", "afterState": ["Booked consultations", "Serviceable-area targeting", "Calendar-driven pipeline", "Demand-matched pacing"], "clientName": "Maisie", "objectives": ["Tie campaigns to booked consultations rather than form fills", "Match targeting to service area and crew capability", "Align spend with seasonal demand"], "serviceKey": "meta-ads", "beforeState": ["Out-of-area enquiries", "Mismatched job requests", "Empty survey calendar", "Flat year-round spend"], "countryCode": "gb", "placeholder": true, "publishedDate": "2025-11-08", "challengePoints": ["Enquiries from outside the serviceable radius", "Requests for job types the business does not deliver", "Flat budget ignoring strong seasonal demand swings"], "projectDuration": "3 months (ongoing retainer)", "clientDescriptor": "Home renovation and fit-out company", "shortDescription": "Paid campaigns rebuilt around booked in-home consultations, with geography and job-type targeting matched to crew capacity."}', '2026-08-17 14:05:37', '2026-08-19 10:19:10', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('08a29c87-6429-48dd-ad1a-6289cb2103c0', 'case_studies', 'enrolment-campaigns-after-tracking-loss-canada', 15, 'published', '{"slug": "enrolment-campaigns-after-tracking-loss-canada", "team": "1 strategist, 1 media buyer, 1 analyst", "title": "Rebuilding enrolment campaigns after signal loss", "country": "Canada", "metrics": [], "features": ["Consent-aware Conversions API implementation", "Offline conversion upload from CRM", "Geo holdout incrementality tests", "Stage-based funnel reporting", "Course-level performance breakdown"], "industry": "Education", "outcomes": ["Campaign decisions are made against enrolment data, not platform estimates", "Leadership reviews one reconciled report instead of three conflicting ones", "Holdout testing shows which campaigns genuinely add enrolments"], "solution": [{"title": "Server-side event layer", "description": "Conversions API with deduplicated events and consent-aware collection."}, {"title": "CRM outcome matching", "description": "Application and enrolment stages returned as offline conversions for optimisation."}, {"title": "Incrementality testing", "description": "Geo holdout tests to measure contribution rather than trusting last-click attribution."}, {"title": "Reconciled reporting", "description": "One dashboard blending platform data, CRM stages and enrolment records."}], "challenge": "After platform tracking restrictions, reported conversions collapsed and nobody could tell which campaigns actually produced enrolments. Decisions were being made on in-platform numbers that contradicted the student information system, and the marketing team was pausing campaigns that were probably working.", "heroImage": "https://medcybnudpmluhledips.supabase.co/storage/v1/object/sign/media/optimized/2026/1787134792743-42vdi-f2ce3356-2ac7-40c2-9651-9f42bf5a5875.webp?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV81NGFlZmZkNi1mNDNlLTRlNGEtOWZkMS01NmFkODFjNTllYzYiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJtZWRpYS9vcHRpbWl6ZWQvMjAyNi8xNzg3MTM0NzkyNzQzLTQydmRpLWYyY2UzMzU2LTJhYzctNDBjMi05NjUxLTlmNDJiZjVhNTg3NS53ZWJwIiwic2NvcGUiOiJkb3dubG9hZCIsImlhdCI6MTc4NzEzNDc5MSwiZXhwIjoxOTQ0ODE0NzkxfQ.VpXiYIsrApyf5mmE82FBB8uZZzvB3vXOMg_DPTkmvHk", "valueProp": "Measurement you can act on, in a restricted-signal world.", "afterState": ["Server-side measurement", "CRM-matched outcomes", "Evidence-based budgeting", "Tested incrementality"], "clientName": "Tenny Koshy", "objectives": ["Restore trustworthy measurement across the enrolment funnel", "Reconnect ad platforms to real enrolment outcomes", "Give leadership one reconciled performance view"], "serviceKey": "meta-ads", "beforeState": ["Collapsed reported conversions", "Platform vs CRM contradictions", "Guesswork budget decisions", "No incrementality view"], "countryCode": "ca", "placeholder": true, "publishedDate": "2025-10-06", "challengePoints": ["Reported conversions diverging sharply from actual enrolments", "No reliable link between ad spend and the student information system", "Decisions being made on contradictory data"], "projectDuration": "5 months (ongoing retainer)", "clientDescriptor": "Private further-education college", "shortDescription": "Attribution rebuilt with server-side events and CRM matching so enrolment campaigns could be optimised again after tracking restrictions."}', '2026-08-17 14:05:37', '2026-08-19 10:20:36', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('79e558e2-5b97-447d-90f0-73ba91b95aee', 'case_studies', 'ecommerce-lifecycle-email-flows-australia', 36, 'published', '{"slug": "ecommerce-lifecycle-email-flows-australia", "team": "1 strategist, 1 copywriter, 1 email developer", "title": "Recovering lost revenue with automated e-commerce lifecycle email", "country": "Australia", "metrics": [], "featured": true, "features": ["Welcome and onboarding sequence", "Abandoned cart and browse abandonment flows", "Post-purchase and review-request emails", "Win-back campaign for lapsed customers", "Engagement-based suppression rules"], "industry": "E-commerce", "outcomes": ["Revenue continues between promotional campaigns instead of dropping to zero", "The team ships a campaign in an afternoon using the template system", "Engagement rates recovered after list cleanup and suppression rules"], "solution": [{"title": "Deliverability reset", "description": "Authentication fixed, the list cleaned and a sunset policy introduced for long-term unengaged contacts."}, {"title": "Five core flows", "description": "Welcome, abandoned cart, browse abandonment, post-purchase and win-back built, written and tested end to end."}, {"title": "Behavioural segmentation", "description": "Segments based on engagement recency, category interest and purchase history instead of one global list."}, {"title": "Reusable template system", "description": "Responsive modular templates the in-house team can assemble without a designer."}], "challenge": "Every sale depended on someone remembering to build a campaign. There were no welcome, cart or post-purchase flows, the list was never segmented, and unengaged contacts were dragging deliverability down. Promotional peaks were followed by weeks of silence.", "valueProp": "Email that keeps selling when nobody is sending.", "afterState": ["Five always-on flows", "Behaviour-based segments", "Healthy inbox placement", "Revenue reported per flow"], "clientName": "[Client Name]", "objectives": ["Launch the core lifecycle flows every store should have running", "Segment the list by engagement and purchase behaviour", "Repair sender reputation and inbox placement"], "serviceKey": "email-marketing", "beforeState": ["Manual sends only", "One unsegmented list", "Declining open rates", "No revenue attribution per email"], "countryCode": "au", "placeholder": true, "publishedDate": "2026-01-22", "challengePoints": ["No automated flows \\u2014 revenue depended on manual campaign sends", "One unsegmented list, so every subscriber received identical messages", "Deliverability slipping because unengaged contacts were never suppressed"], "projectDuration": "8 weeks", "clientDescriptor": "Direct-to-consumer lifestyle brand", "shortDescription": "A brand relying only on manual campaign blasts moved to five automated lifecycle flows that keep working between promotions."}', '2026-08-19 10:29:09', '2026-08-19 10:29:09', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('d9c859b8-e6de-42b6-b792-63af0c0c6097', 'case_studies', 'b2b-cold-email-pipeline-usa', 37, 'published', '{"slug": "b2b-cold-email-pipeline-usa", "team": "1 strategist, 1 copywriter, 1 automation specialist", "title": "Building a compliant cold email system that books qualified calls", "country": "United States", "metrics": [], "features": ["Warmed-up outbound sending domains", "Verified, manually qualified prospect lists", "Per-segment sequence copy and follow-ups", "Reply classification and routing", "CRM logging with sequence-level reporting"], "industry": "Professional services", "outcomes": ["The primary domain is no longer exposed to outbound reputation risk", "Sales knows which segments and angles actually produce conversations", "Replies reach a human the same day instead of sitting unread"], "solution": [{"title": "Sending infrastructure", "description": "Separate outbound domains, authentication and a staged warm-up schedule with sensible daily limits."}, {"title": "List building & verification", "description": "Narrow ICP definitions, manual qualification and verification before any contact is loaded."}, {"title": "Segment-led sequences", "description": "Short, specific sequences per industry and role, each with a distinct angle and single ask."}, {"title": "Reply handling & CRM sync", "description": "Routing rules, response templates and full logging so replies reach a human quickly."}], "challenge": "The team blasted the same template to bought lists from their main domain. Replies were rare, spam complaints were rising, and the primary domain''s reputation was at risk. Nobody could tell which message or segment produced the few meetings that did happen.", "valueProp": "Fewer emails, better lists, more replies.", "afterState": ["Segment-specific sequences", "Verified lists", "Isolated sending infrastructure", "Meetings attributed to sequences"], "clientName": "[Client Name]", "objectives": ["Protect the primary domain while scaling outbound safely", "Replace generic messaging with segment-specific sequences", "Attribute every booked call to a sequence and segment"], "serviceKey": "email-marketing", "beforeState": ["One generic template", "Bought lists", "Primary domain at risk", "No attribution"], "countryCode": "us", "placeholder": true, "publishedDate": "2025-12-05", "challengePoints": ["One generic template sent to broad, unverified lists", "Sending from the primary domain with no warm-up, risking reputation", "No tracking of which sequence or segment produced meetings"], "projectDuration": "10 weeks", "clientDescriptor": "B2B professional services firm", "shortDescription": "Outbound email rebuilt from generic mass sends into tightly targeted sequences with warm-up, reply handling and CRM tracking."}', '2026-08-19 10:29:09', '2026-08-19 10:29:09', NULL);
INSERT IGNORE INTO `cms_collections` (`id`, `collection`, `slug`, `sort`, `status`, `data`, `created_at`, `updated_at`, `updated_by`) VALUES ('efc40ff8-40b3-427c-9833-446be88a31fb', 'case_studies', 'saas-onboarding-nurture-email-netherlands', 38, 'published', '{"slug": "saas-onboarding-nurture-email-netherlands", "team": "1 strategist, 1 copywriter, 1 lifecycle specialist", "title": "Turning trial signups into activated users with nurture email", "country": "Netherlands", "metrics": [], "features": ["Product-event triggered sequences", "Branching onboarding by setup progress", "Step-specific stall recovery emails", "Trial-end value recap and upgrade prompts", "Expired-trial win-back sequence"], "industry": "SaaS", "outcomes": ["Users who stall at setup now get help about the exact step they abandoned", "Product and marketing share one definition of activation", "Trial endings are a planned conversation instead of silence"], "solution": [{"title": "Activation definition", "description": "Agreed the events that represent real first value, then instrumented them as email triggers."}, {"title": "Behavioural onboarding track", "description": "Branching sequences that respond to setup progress rather than sending on a fixed schedule."}, {"title": "Stall recovery emails", "description": "Step-specific help, short walkthroughs and a human offer when a user abandons a setup stage."}, {"title": "Trial-end and expansion track", "description": "Value recap, upgrade paths and win-back messaging for expired trials."}], "challenge": "Signups were healthy but activation was not. New users got a single welcome email regardless of what they did in the product, so those who stalled at setup were never nudged and those who succeeded were never moved toward upgrading.", "valueProp": "Onboarding email that reacts to what users actually do.", "afterState": ["Behaviour-triggered onboarding", "Instrumented activation events", "Stall recovery in place", "Structured trial-end track"], "clientName": "[Client Name]", "objectives": ["Trigger email from real product behaviour", "Guide stalled trials past the specific step they abandoned", "Give activated users a clear upgrade path before trial expiry"], "serviceKey": "email-marketing", "beforeState": ["Single welcome email", "No product event triggers", "Stalled trials unnoticed", "No trial-end messaging"], "countryCode": "nl", "placeholder": true, "publishedDate": "2025-11-18", "challengePoints": ["One-size-fits-all welcome email with no follow-up", "No product events feeding email, so stalled users were invisible", "No distinct path for activated users approaching trial end"], "projectDuration": "7 weeks", "clientDescriptor": "B2B SaaS product team", "shortDescription": "Trial users received one welcome email and nothing else. A behaviour-triggered onboarding track now guides them to first value."}', '2026-08-19 10:29:09', '2026-08-19 10:29:09', NULL);
